import type { Pipeline } from "../components/pipeline/types";
import { validateResourceMap } from "./pipelineResourceValidation";

export type PipelineValidationResult = {
	valid: boolean;
	errors: string[];
	warnings: string[];
};

function splitRef(ref: string): { nodeId: string; port: string } {
	const dot = ref.lastIndexOf(".");
	if (dot < 0) return { nodeId: ref, port: "" };
	return { nodeId: ref.slice(0, dot), port: ref.slice(dot + 1) };
}

function safeParamName(value: string) {
	return value.replace(/\./g, "-");
}

function componentWritesOutputPath(
	component: Pipeline["nodes"][number]["component"],
	outputName: string,
) {
	const path = `/tmp/outputs/${outputName}`;
	if (component.source?.includes(path)) return true;
	if (component.command?.some((part) => part.includes(path))) return true;
	if (component.args?.some((arg) => arg.value?.includes(path))) return true;
	return false;
}

function nodeDeclaresOutput(
	node: Pipeline["nodes"][number] | undefined,
	portName: string,
) {
	if (!node) return false;
	const safe = safeParamName(portName);
	return (node.outputs || []).some(
		(port) => port.name === portName || safeParamName(port.name) === safe,
	);
}

function nodeMode(node: Pipeline["nodes"][number]): string {
	const component = node.component as Pipeline["nodes"][number]["component"] & {
		mode?: string;
	};
	return typeof component.mode === "string" ? component.mode.trim() : "";
}

function validateContainerEntrypoints(
	nodes: Pipeline["nodes"],
	prefix = "",
): string[] {
	const errors: string[] = [];
	for (const node of nodes || []) {
		const label = prefix ? `${prefix}.${node.id}` : node.id;
		const subNodes = node.subNodes ?? [];
		const hasSubNodes = subNodes.length > 0;
		const image = node.component.image?.trim() ?? "";
		const command = node.component.command ?? [];
		const args = node.component.args ?? [];
		if (
			nodeMode(node) !== "script" &&
			!hasSubNodes &&
			image &&
			command.length === 0 &&
			args.length === 0
		) {
			errors.push(
				`节点「${label}」缺少容器命令或参数。请编辑该节点，补充 Command 或 Args 后再运行。`,
			);
		}
		if (hasSubNodes) {
			errors.push(...validateContainerEntrypoints(subNodes, label));
		}
	}
	return errors;
}

export function validatePipelineForRun(
	pipeline: Pipeline,
): PipelineValidationResult {
	const errors: string[] = [];
	const warnings: string[] = [];
	const nodesById = new Map(pipeline.nodes.map((node) => [node.id, node]));
	const targetBindings = new Map<string, string>();

	for (const edge of pipeline.edges || []) {
		const source = splitRef(edge.source);
		const target = splitRef(edge.target);
		if (target.nodeId && target.port) {
			const key = `${target.nodeId}.${safeParamName(target.port)}`;
			const prior = targetBindings.get(key);
			if (prior) {
				errors.push(
					`输入端口 ${key} 已连接 ${prior}，不能再连接 ${edge.source}。请为汇聚节点配置不同输入端口。`,
				);
			} else {
				targetBindings.set(key, edge.source);
			}
		}

		if (!source.nodeId || !source.port) continue;
		const sourceNode = nodesById.get(source.nodeId);
		if (!nodeDeclaresOutput(sourceNode, source.port)) continue;
		if (
			sourceNode &&
			!componentWritesOutputPath(sourceNode.component, source.port)
		) {
			warnings.push(
				`输出 ${edge.source} 被 ${edge.target} 消费，但组件脚本没有写入 /tmp/outputs/${source.port}；运行时实际写入由容器决定，此检查为静态推测。`,
			);
		}

		// Check port type compatibility
		if (sourceNode && target.nodeId && target.port) {
			const targetNode = nodesById.get(target.nodeId);
			if (targetNode) {
				const srcPort = (sourceNode.outputs || []).find(
					(p) =>
						p.name === source.port ||
						safeParamName(p.name) === safeParamName(source.port),
				);
				const tgtPort = (targetNode.inputs || []).find(
					(p) =>
						p.name === target.port ||
						safeParamName(p.name) === safeParamName(target.port),
				);
				if (srcPort && tgtPort && srcPort.type !== tgtPort.type) {
					warnings.push(
						`端口类型不匹配：${edge.source}(${srcPort.type}) → ${edge.target}(${tgtPort.type})`,
					);
				}
			}
		}
	}

	for (const node of pipeline.nodes || []) {
		errors.push(
			...validateResourceMap(
				node.component.resources,
				`节点 ${node.id} 资源配置`,
			),
		);
		for (const output of node.outputs || []) {
			if (!componentWritesOutputPath(node.component, output.name)) {
				warnings.push(
					`${node.id}.${output.name} 未写入 /tmp/outputs/${output.name}；未连接时不会影响运行，连接下游前需要补输出文件。`,
				);
			}
		}
	}
	errors.push(...validateContainerEntrypoints(pipeline.nodes || []));

	return { valid: errors.length === 0, errors, warnings };
}
