export type PipelineFlowNode = Node<PipelineNodeData>;
export type PipelineFlowEdge = Edge;

export function toRecord<T extends { id: string }>(
	items: T[],
): Record<string, T> {
	return items.reduce<Record<string, T>>((acc, item) => {
		acc[item.id] = item;
		return acc;
	}, {});
}

export function dedupeComponentsByName(
	comps: RegisteredComponent[],
): RegisteredComponent[] {
	const seen = new Set<string>();
	return comps.filter((c) => {
		const key = c.name.trim().toLowerCase();
		if (!key || seen.has(key)) return false;
		seen.add(key);
		return true;
	});
}

const AUTO_ADD_NODE_WIDTH = 260;
const AUTO_ADD_NODE_X_GAP = 80;
const AUTO_ADD_NODE_Y_GAP = 64;
const AUTO_ADD_START_X = 180;
const AUTO_ADD_START_Y = 140;

export function getAutoAddNodeScreenPosition(
	nodeCount: number,
	bounds?: Pick<DOMRect, "left" | "top" | "width"> | null,
): { x: number; y: number } {
	const stepX = AUTO_ADD_NODE_WIDTH + AUTO_ADD_NODE_X_GAP;
	const stepY = 120 + AUTO_ADD_NODE_Y_GAP;
	const availableWidth = Math.max(0, (bounds?.width ?? 0) - AUTO_ADD_START_X);
	const columns = Math.max(1, Math.floor(availableWidth / stepX));
	const column = nodeCount % columns;
	const row = Math.floor(nodeCount / columns);

	return {
		x: (bounds?.left ?? 0) + AUTO_ADD_START_X + column * stepX,
		y: (bounds?.top ?? 0) + AUTO_ADD_START_Y + row * stepY,
	};
}

function normalizeComponentType(
	type: string | undefined,
): PipelineComponentType {
	const value = (type || "").trim();
	switch (value) {
		case "container":
		case "script":
		case "resource":
		case "suspend":
			return value;
		default:
			return "container";
	}
}

function normalizePorts(ports: Port[] | undefined, fallback: Port[]): Port[] {
	if (!ports || ports.length === 0) return fallback;
	const seen = new Set<string>();
	const next: Port[] = [];
	for (const port of ports) {
		const name = port.name?.trim();
		if (!name || seen.has(name)) continue;
		seen.add(name);
		next.push({
			name,
			type: port.type?.trim() || "string",
			...(port.desc?.trim() ? { desc: port.desc.trim() } : {}),
			...(port.default_value?.trim()
				? { default_value: port.default_value.trim() }
				: {}),
		});
	}
	return next.length > 0 ? next : fallback;
}

export function uniqSorted(values: string[]): string[] {
	return Array.from(new Set(values.filter(Boolean))).sort();
}

function normalizeTolerations(items: unknown): Toleration[] {
	if (!Array.isArray(items)) return [];
	return items
		.map((item) => {
			if (!item || typeof item !== "object") return null;
			const record = item as Record<string, unknown>;
			const key = typeof record.key === "string" ? record.key.trim() : "";
			const operator =
				typeof record.operator === "string" ? record.operator.trim() : "";
			const value = typeof record.value === "string" ? record.value.trim() : "";
			const effect =
				typeof record.effect === "string" ? record.effect.trim() : "";
			const rawSeconds = record.tolerationSeconds;
			const tolerationSeconds =
				typeof rawSeconds === "number" && Number.isFinite(rawSeconds)
					? rawSeconds
					: typeof rawSeconds === "string" && rawSeconds.trim() !== ""
						? Number(rawSeconds)
						: undefined;
			if (
				!key &&
				!operator &&
				!value &&
				!effect &&
				tolerationSeconds === undefined
			) {
				return null;
			}
			return {
				...(key ? { key } : {}),
				...(operator ? { operator } : {}),
				...(value ? { value } : {}),
				...(effect ? { effect } : {}),
				...(tolerationSeconds !== undefined &&
				Number.isFinite(tolerationSeconds)
					? { tolerationSeconds }
					: {}),
			};
		})
		.filter((item): item is Toleration => Boolean(item));
}

function normalizeVolumeMounts(value: unknown): VolumeMount[] {
	if (!Array.isArray(value)) return [];
	const mounts: VolumeMount[] = [];
	for (const item of value) {
		if (!item || typeof item !== "object") continue;
		const record = item as Record<string, unknown>;
		const name = typeof record.name === "string" ? record.name.trim() : "";
		const mountPath =
			typeof record.mountPath === "string" ? record.mountPath.trim() : "";
		const pvcName =
			typeof record.pvcName === "string" ? record.pvcName.trim() : "";
		const secretProviderClass =
			typeof record.secretProviderClass === "string" // pragma: allowlist secret
				? record.secretProviderClass.trim()
				: "";
		const csiDriver =
			typeof record.csiDriver === "string" ? record.csiDriver.trim() : "";
		const emptyDir = record.emptyDir === true;
		if (!name && !mountPath && !pvcName && !secretProviderClass && !emptyDir) {
			continue;
		}
		const type: VolumeMount["type"] =
			secretProviderClass || csiDriver ? "csi" : pvcName ? "pvc" : "emptyDir";
		mounts.push({
			type,
			name,
			mountPath,
			...(typeof record.subPath === "string" && record.subPath.trim()
				? { subPath: record.subPath.trim() }
				: {}),
			...(record.readOnly === true ? { readOnly: true } : {}),
			...(pvcName ? { pvcName } : {}),
			...(emptyDir || type === "emptyDir" ? { emptyDir: true } : {}),
			...(csiDriver ? { csiDriver } : {}),
			...(secretProviderClass ? { secretProviderClass } : {}),
		});
	}
	return mounts;
}

function normalizeInlineFiles(value: unknown): InlineFile[] {
	if (!Array.isArray(value)) return [];
	return value.flatMap((item) => {
		if (!item || typeof item !== "object") return [];
		const record = item as Record<string, unknown>;
		const filePath = typeof record.path === "string" ? record.path.trim() : "";
		const content = typeof record.content === "string" ? record.content : "";
		if (!filePath && !content) return [];
		return [{ path: filePath, content }];
	});
}

function buildDefaultConfig(comp: RegisteredComponent): NodeDefaultConfig {
	return {
		command: comp.command || [],
		args: comp.args || [],
		source: comp.source || "",
		env: comp.env || [],
		cpu: comp.cpu || "",
		memory: comp.memory || "",
		disk: comp.disk || "",
		gpu: comp.gpu || "",
		computeTier: comp.computeTier || "",
		tolerations: comp.tolerations || [],
		volumeMounts: comp.volumeMounts || [],
		inlineFiles: comp.inlineFiles || [],
	};
}

export function toStringArray(value: unknown): string[] {
	if (typeof value === "string") return [value].filter(Boolean);
	if (!Array.isArray(value)) return [];
	return value
		.map((item) => (typeof item === "string" ? item.trim() : ""))
		.filter((item) => item.length > 0);
}

export function parseAssetIds(raw: string | null | undefined): string[] {
	if (!raw) return [];
	return raw
		.split(",")
		.map((item) => item.trim())
		.filter((item) => item.length > 0);
}

export function extractNodeAssetIds(node: PipelineFlowNode | null): string[] {
	if (!node) return [];
	const data = node.data as Record<string, unknown>;
	const direct = uniqSorted([
		...toStringArray(data.asset_id),
		...toStringArray(data.assetId),
		...toStringArray(data.input_asset_id),
		...toStringArray(data._input_asset_id),
		...toStringArray(data.asset_ids),
		...toStringArray(data.assetIds),
		...toStringArray(data.input_asset_ids),
		...toStringArray(data._input_asset_ids),
	]);
	const fromAssetSelection = toStringArray(
		(data.assetSelection as Record<string, unknown> | undefined)?.assetIds,
	);
	return uniqSorted([...direct, ...fromAssetSelection]);
}

export function extractPipelineAssetIds(
	pipeline: Pipeline | Record<string, unknown>,
): string[] {
	const contract = pipeline as Record<string, unknown>;
	return uniqSorted([
		...toStringArray(contract._input_asset_ids),
		...toStringArray(contract.input_asset_ids),
		...toStringArray(
			(contract.input as Record<string, unknown> | undefined)?.asset_ids,
		),
		...toStringArray(
			(contract.assetSelection as Record<string, unknown> | undefined)
				?.assetIds,
		),
	]);
}

export function formatBytes(bytes: unknown): string {
	const n = typeof bytes === "string" ? Number(bytes) : bytes;
	if (typeof n !== "number" || !Number.isFinite(n) || n < 0) return "—";
	if (n === 0) return "0 B";
	const units = ["B", "KB", "MB", "GB", "TB", "PB"];
	let size = n;
	let i = 0;
	while (size >= 1024 && i < units.length - 1) {
		size /= 1024;
		i += 1;
	}
	return `${size.toFixed(i === 0 ? 0 : 2)} ${units[i]}`;
}

function toNumber(value: unknown): number | null {
	if (typeof value === "number") {
		return Number.isFinite(value) ? value : null;
	}
	if (typeof value === "string") {
		const parsed = Number(value);
		return Number.isFinite(parsed) ? parsed : null;
	}
	return null;
}

export function extractAssetSizeBytes(
	raw: Record<string, unknown>,
): number | null {
	const directSize =
		toNumber(raw.size) ??
		toNumber(raw.size_bytes) ??
		toNumber((raw as { bytes?: unknown }).bytes);
	if (directSize !== null) return directSize;

	const directNested = [raw.metadata, raw.files_json];
	for (const nested of directNested) {
		if (nested && typeof nested === "object") {
			const candidate = nested as Record<string, unknown>;
			const candidateSize =
				toNumber(candidate.size) ??
				toNumber(candidate.size_bytes) ??
				toNumber(candidate.byte_size) ??
				toNumber(candidate.bytes);
			if (candidateSize !== null) return candidateSize;
		}
	}

	if (raw.files_json && typeof raw.files_json === "object") {
		for (const value of Object.values(
			raw.files_json as Record<string, unknown>,
		)) {
			if (!value || typeof value !== "object") continue;
			const fileMeta = value as Record<string, unknown>;
			const fromFile =
				toNumber(fileMeta.size) ??
				toNumber(fileMeta.size_bytes) ??
				toNumber(fileMeta.byte_size) ??
				toNumber(fileMeta.bytes);
			if (fromFile !== null) return fromFile;
		}
	}

	return null;
}

export function parseAssetName(
	asset: Record<string, unknown>,
	fallbackId: string,
): string {
	if (typeof asset.name === "string" && asset.name.trim()) return asset.name;
	if (typeof asset.display_name === "string" && asset.display_name.trim()) {
		return asset.display_name;
	}
	return fallbackId || "—";
}

export function parseAssetType(
	asset: Record<string, unknown>,
	fallback: string,
): string {
	if (typeof asset.asset_type === "string" && asset.asset_type.trim()) {
		return asset.asset_type;
	}
	if (typeof asset.type === "string" && asset.type.trim()) {
		return asset.type;
	}
	return fallback;
}

export function apiToRegistered(
	api: PipelineComponentAPI,
): RegisteredComponent {
	const resources = api.resources ?? {};
	const normalizedType = normalizeComponentType(api.type);
	const normalizedSource = (api.source || "custom").trim() || "custom";
	const envFromObject = api.env
		? Object.entries(api.env).map(([name, value]) => ({
				name,
				value: value || "",
			}))
		: [];
	const envFromResource =
		Array.isArray(resources.env) && resources.env.length > 0
			? (resources.env as { name?: string; value?: string }[]).map((item) => ({
					name: item.name || "",
					value: item.value || "",
				}))
			: typeof resources.env === "object" && resources.env
				? Object.entries(resources.env as Record<string, string>).map(
						([name, value]) => ({
							name,
							value: value || "",
						}),
					)
				: [];
	return {
		id: api.id,
		name: api.name,
		type: normalizedType,
		source: normalizedSource,
		image: formatImage(api.image, api.tag),
		tag: api.tag,
		command: api.command ?? ((resources.command as string[]) || ["sh", "-c"]),
		args: normalizeComponentArgs(
			(api.args && api.args.length > 0
				? api.args
				: Array.isArray(resources.args)
					? resources.args
					: undefined) as unknown[],
		),
		env: envFromObject.length > 0 ? envFromObject : envFromResource,
		inputPorts: normalizePorts(api.inputPorts, [
			{ name: "input", type: "asset" },
		]),
		outputPorts: normalizePorts(api.outputPorts, [
			{ name: "output", type: "asset" },
		]),
		cpu: (resources.cpu as string) ?? "",
		memory: (resources.memory as string) ?? "",
		disk: (resources.disk as string) ?? "",
		gpu: (resources.gpu as string) ?? "",
		computeTier: (resources.computeTier as string) ?? "",
		tolerations: normalizeTolerations(resources.tolerations),
		volumeMounts: normalizeVolumeMounts(resources.volumeMounts),
		inlineFiles: normalizeInlineFiles(resources.inlineFiles),
	};
}

let nodeCounter = 0;

export function createPipelineNode(
	comp: RegisteredComponent,
	x: number,
	y: number,
): PipelineFlowNode {
	nodeCounter += 1;
	return {
		id: `step-${nodeCounter}`,
		type: "pipelineStep",
		position: { x, y },
		data: {
			label: comp.name,
			type: comp.type || "container",
			source: comp.source || "",
			image: comp.image,
			command: comp.command,
			args: comp.args || [],
			env: comp.env || [],
			inputPorts: comp.inputPorts || [{ name: "input", type: "asset" }],
			outputPorts: comp.outputPorts || [{ name: "output", type: "asset" }],
			cpu: comp.cpu || "",
			memory: comp.memory || "",
			disk: comp.disk || "",
			gpu: comp.gpu || "",
			computeTier: comp.computeTier || "",
			tolerations: comp.tolerations || [],
			volumeMounts: comp.volumeMounts || [],
			inlineFiles: comp.inlineFiles || [],
			defaultConfig: buildDefaultConfig(comp),
			selectType: SelectType.DEFAULT,
		},
	};
}
