export type ComputeProfileId =
	| "custom"
	| "cpu-standard"
	| "cpu-large"
	| "gpu-l4"
	| "gpu-a100";

export interface ComputeProfile {
	id: ComputeProfileId;
	label: string;
	description: string;
	cpu: string;
	memory: string;
	disk: string;
	gpu: string;
	computeTier: string;
}

const computeProfiles: Record<ComputeProfileId, ComputeProfile> = {
	custom: {
		id: "custom",
		label: "自定义",
		description: "手动填写 CPU、内存、磁盘和 GPU 数量。",
		cpu: "",
		memory: "",
		disk: "",
		gpu: "",
		computeTier: "",
	},
	"cpu-standard": {
		id: "cpu-standard",
		label: "CPU 标准",
		description: "轻量 CPU 任务。",
		cpu: "500m",
		memory: "2Gi",
		disk: "5Gi",
		gpu: "0",
		computeTier: "cpu-standard",
	},
	"cpu-large": {
		id: "cpu-large",
		label: "CPU 大内存",
		description: "更高 CPU/内存吞吐。",
		cpu: "2",
		memory: "8Gi",
		disk: "20Gi",
		gpu: "0",
		computeTier: "cpu-large",
	},
	"gpu-l4": {
		id: "gpu-l4",
		label: "GPU L4",
		description: "轻量 GPU 任务。",
		cpu: "4",
		memory: "16Gi",
		disk: "20Gi",
		gpu: "1",
		computeTier: "gpu-l4",
	},
	"gpu-a100": {
		id: "gpu-a100",
		label: "GPU A100",
		description: "高性能 GPU 任务。",
		cpu: "4",
		memory: "32Gi",
		disk: "50Gi",
		gpu: "1",
		computeTier: "gpu-a100",
	},
};

export const PRESET_COMPUTE_PROFILES: ComputeProfile[] = Object.values(
	computeProfiles,
).filter(
	(item): item is Exclude<ComputeProfile, { id: "custom" }> =>
		item.id !== "custom",
);

const computeProfileMap = PRESET_COMPUTE_PROFILES.reduce(
	(acc, profile) => {
		acc[profile.id as Exclude<ComputeProfileId, "custom">] = profile;
		return acc;
	},
	{} as Record<Exclude<ComputeProfileId, "custom">, ComputeProfile>,
);

export const computeProfileOptions = [
	{ value: "custom", label: computeProfiles.custom.label },
	...PRESET_COMPUTE_PROFILES.map((profile) => ({
		value: profile.id,
		label: profile.label,
	})),
];

interface ResourceValues {
	cpu?: string;
	memory?: string;
	disk?: string;
	gpu?: string;
	computeTier?: string;
}

function normalizeResourceValue(value: string | undefined): string {
	return (value || "").trim() || "-";
}

function normalizeGpuValue(value: string | undefined): string {
	const normalized = (value || "").trim();
	return normalized.length > 0 ? normalized : "0";
}

function normalizeText(value: string | undefined): string {
	return (value || "").trim();
}

function normalizeOptionalText(value: string | undefined): string {
	return (value || "").trim().toLowerCase();
}

function profileFromId(id: string | undefined): ComputeProfile | null {
	if (!id || id === "custom") return null;
	return computeProfileMap[id as Exclude<ComputeProfileId, "custom">] ?? null;
}

export function getComputeProfileById(
	id: ComputeProfileId,
): ComputeProfile | null {
	return profileFromId(id);
}

export function inferComputeProfile(values: ResourceValues): ComputeProfileId {
	const cpu = normalizeText(values.cpu);
	const memory = normalizeText(values.memory);
	const disk = normalizeText(values.disk);
	const gpu = normalizeText(values.gpu);
	const computeTier = normalizeOptionalText(values.computeTier);
	const hasComputeTier = computeTier.length > 0;

	if (!cpu && !memory && !disk && !gpu) {
		return "custom";
	}

	for (const profile of PRESET_COMPUTE_PROFILES) {
		const sameResourceCore =
			profile.cpu === cpu &&
			profile.memory === memory &&
			profile.disk === disk &&
			profile.gpu === gpu;

		if (
			sameResourceCore &&
			(!hasComputeTier ||
				normalizeOptionalText(profile.computeTier) === computeTier)
		) {
			return profile.id;
		}
	}
	return "custom";
}

export function buildResourceValues(
	profileId: ComputeProfileId,
): ResourceValues {
	const profile = profileFromId(profileId) || profileFromId("custom");
	return {
		cpu: profile?.cpu ?? "",
		memory: profile?.memory ?? "",
		disk: profile?.disk ?? "",
		gpu: profile?.gpu ?? "",
		computeTier: profile?.computeTier ?? "",
	};
}

export function buildResourceSummary(profile: ComputeProfile): string {
	return `CPU ${profile.cpu}, 内存 ${profile.memory}, 磁盘 ${profile.disk}, GPU ${profile.gpu || "0"}, ${profile.computeTier || "-"}`;
}

export function buildResourceSummaryFromValues(values: ResourceValues): string {
	return `CPU ${normalizeResourceValue(
		values.cpu,
	)}，内存 ${normalizeResourceValue(values.memory)}，磁盘 ${normalizeResourceValue(
		values.disk,
	)}，GPU ${normalizeGpuValue(values.gpu)}，${(values.computeTier || "").trim() || "-"}`;
}
