type WorkflowErrorKind = "network" | "service-unavailable";

type WorkflowErrorState = {
	kind: WorkflowErrorKind;
	message: string;
};

const ARCHIVED_RUN_RETRY_OPERATION: WorkflowOperationConfig = {
	key: "retry",
	title: "重新运行",
	disabled: false,
	danger: false,
	run: async () => ({ message: "retry submitted" }),
};

const ARCHIVED_RUN_DELETE_OPERATION: WorkflowOperationConfig = {
	key: "delete",
	title: "删除",
	disabled: false,
	danger: true,
	run: async () => ({ message: "delete submitted" }),
};

const LIVE_STATUS_FILTERS = new Set(["Running", "Pending"]);
const WORKFLOW_OPERATION_STATUSES = new Set([
	"Running",
	"Pending",
	"Suspended",
]);

const hasLiveWorkflowOperations = (status?: string): boolean =>
	WORKFLOW_OPERATION_STATUSES.has((status || "").trim());

const canDeleteExecutionRecord = (record: ExecutionListRow): boolean =>
	record.liveAvailable || !!record.runId;

const getExecutionOperationConfig = (
	record: ExecutionListRow,
	key: WorkflowOperationKey,
): WorkflowOperationConfig | undefined => {
	if (record.historyOnly && record.runId) {
		const runId = record.runId;
		if (key === "retry") {
			return {
				...ARCHIVED_RUN_RETRY_OPERATION,
				run: async () => {
					await retryPipelineRun(runId);
					return { message: "retry submitted" };
				},
			};
		}
		if (key === "delete") {
			return {
				...ARCHIVED_RUN_DELETE_OPERATION,
				run: async () => {
					await deletePipelineRun(runId);
					return { message: "delete submitted" };
				},
			};
		}
	}
	if (record.historyOnly) return undefined;

	return getAvailableWorkflowOperationConfigs(record).find(
		(item) => item.key === key,
	);
};

const parseDate = (value: string | null): Dayjs | null => {
	if (!value) return null;
	const parsed = dayjs(value);
	return parsed.isValid() ? parsed : null;
};

const renderTimestamp = (value?: string) => {
	if (!value) return "-";
	const parsed = dayjs(value);
	if (!parsed.isValid()) return new Date(value).toLocaleString();
	const absolute = parsed.format("YYYY-MM-DD HH:mm:ss");
	return (
		<Tooltip title={parsed.toDate().toLocaleString()}>
			<div style={{ lineHeight: 1.35 }}>
				<div>{absolute}</div>
				<Typography.Text type="secondary" style={{ fontSize: 12 }}>
					{parsed.fromNow()}
				</Typography.Text>
			</div>
		</Tooltip>
	);
};

const datesEqual = (a: Dayjs | null, b: Dayjs | null): boolean => {
	if (!a && !b) return true;
	if (!a || !b) return false;
	return a.isSame(b);
};

const arraysEqual = (a: string[], b: string[]): boolean => {
	if (a.length !== b.length) return false;
	return a.every((value, idx) => value === b[idx]);
};

const normalizeStatus = (value: string | null): string | undefined => {
	const trimmed = value?.trim();
	if (!trimmed) return undefined;
	return WORKFLOW_PHASES.includes(trimmed as (typeof WORKFLOW_PHASES)[number])
		? trimmed
		: undefined;
};

const describeWorkflowError = (err: unknown): WorkflowErrorState => {
	const message =
		err instanceof Error
			? err.message
			: typeof err === "string"
				? err
				: "请求失败，请稍后重试";

	const normalized = message.toLowerCase();
	if (
		normalized.includes("failed to fetch") ||
		normalized.includes("network") ||
		normalized.includes("econnrefused") ||
		normalized.includes("enotfound") ||
		normalized.includes("timeout") ||
		normalized.includes("typeerror")
	) {
		return {
			kind: "network",
			message,
		};
	}

	return {
		kind: "service-unavailable",
		message,
	};
};

const getErrorTitle = (kind: WorkflowErrorKind): string =>
	kind === "network" ? "网络错误" : "服务不可用";

const normalizeSearchValue = (value: string) => value.trim().toLowerCase();

const isFailedExecutionStatus = (status?: string) => {
	const normalized = (status || "").trim().toLowerCase();
	return normalized === "failed" || normalized === "error";
};

const formatTriggerSource = (value?: string) => {
	switch ((value || "").trim()) {
		case "manual":
			return "手动运行";
		case "asset_run":
			return "资产运行";
		case "batch":
			return "批量任务";
		case "backfill":
			return "回填运行";
		case "api":
			return "API 运行";
		default:
			return "";
	}
};

const copyExecutionText = async (value: string, label = "ID") => {
	try {
		await navigator.clipboard.writeText(value);
		message.success(`已复制 ${label}`);
	} catch {
		message.error("复制失败");
	}
};

