const looksLikeShardChildRun = (run?: PipelineRunSummary): boolean => {
	if (!run || (run.totalShards ?? 0) > 0) return false;
	const workflowName = run.workflowName || "";
	const pipelineName = run.pipelineName || "";
	return (
		/-shard-\d{3}/i.test(workflowName) || /-shard-\d{3}/i.test(pipelineName)
	);
};

const renderCompactMetric = (
	primary: ReactNode,
	secondary?: ReactNode,
): ReactNode => (
	<div className="pipeline-execution-cell-stack">
		<Typography.Text strong>{primary}</Typography.Text>
		{secondary ? (
			<Typography.Text type="secondary" style={{ fontSize: 12 }}>
				{secondary}
			</Typography.Text>
		) : null}
	</div>
);

const renderFailureMetric = (record: ExecutionListRow) => {
	const failedShards = record.failedShards ?? 0;
	const failedNodes = record.failedNodes ?? 0;
	const failedChildren = record.failedCount ?? 0;
	const totalFailed = Math.max(failedShards, failedNodes, failedChildren);
	const failedStatus = isFailedExecutionStatus(record.status);
	const summary = failedStatus ? record.failureSummary?.trim() : "";
	if (totalFailed <= 0 && !failedStatus) {
		return renderCompactMetric("0", "无失败");
	}
	return (
		<div className="pipeline-execution-cell-stack">
			<Tag color="red" style={{ width: "fit-content" }}>
				{totalFailed > 0 ? totalFailed : "有异常"}
			</Tag>
			{summary ? (
				<Typography.Text
					type="secondary"
					className="pipeline-execution-failure__text"
					title={summary}
					style={{ fontSize: 12 }}
				>
					{summary}
				</Typography.Text>
			) : null}
		</div>
	);
};

const renderResourcePriority = (record: ExecutionListRow) => {
	const priority = record.priority || "normal";
	const resourcePool = record.resourcePool || "default";
	const queueName = record.queueName;
	return (
		<div className="pipeline-execution-cell-stack">
			<Tag
				color={
					priority === "high" || priority === "urgent" ? "volcano" : "blue"
				}
			>
				{priority}
			</Tag>
			<Typography.Text type="secondary" style={{ fontSize: 12 }}>
				{queueName ? `${resourcePool} · ${queueName}` : resourcePool}
			</Typography.Text>
		</div>
	);
};

const getDisplayAssetMetric = (record: ExecutionListRow): ReactNode => {
	if (typeof record.assetCount === "number" && record.assetCount > 0) {
		return record.assetCount;
	}
	const assetIds = Array.isArray(record.assetIds) ? record.assetIds : [];
	if (assetIds.length > 0) return assetIds.length;
	if (record.kind === "run" && (record.assetCount ?? 0) === 0) return "无资产";
	return record.assetCount ?? "-";
};

const getDisplayNodeMetric = (record: ExecutionListRow): ReactNode => {
	const logicalNodeCount = record.nodeCount;
	const totalRuntimeNodes = record.totalNodes ?? 0;
	if (record.kind === "run" && (record.totalShards ?? 0) === 0) {
		return typeof logicalNodeCount === "number" && logicalNodeCount > 0
			? logicalNodeCount
			: totalRuntimeNodes || "-";
	}
	const total =
		totalRuntimeNodes > 0
			? totalRuntimeNodes
			: typeof logicalNodeCount === "number" && logicalNodeCount > 0
				? logicalNodeCount
				: undefined;
	if (!total) return "-";
	const completed = record.completedNodes ?? 0;
	return totalRuntimeNodes > 0 ? `${completed}/${total}` : total;
};

const buildExecutionRows = (
	runs: PipelineExecutionItem[],
): ExecutionListRow[] => {
	const rows: ExecutionListRow[] = [];

	for (const item of runs) {
		if (item.kind === "batch" && item.batch) {
			const batch = item.batch;
			const batchName = batch.name || batch.pipelineName || batch.batchRunId;
			rows.push({
				kind: "batch",
				key: `batch-${batch.batchRunId}`,
				name: batchName,
				status: batch.status,
				nodeCount: batch.nodeCount,
				assetCount: batch.assetCount,
				createdAt: batch.createdAt,
				finishedAt: batch.finishedAt,
				totalEstimatedCost: undefined,
				runId: undefined,
				batchRunId: batch.batchRunId,
				templateId: batch.templateId,
				templateName: batch.templateName || batch.pipelineName,
				templateVersion: batch.templateVersion,
				triggerSource: batch.triggerSource,
				childCount: batch.childCount,
				succeededCount: batch.succeededCount,
				runningCount: batch.runningCount,
				pendingCount: batch.pendingCount,
				failedCount: batch.failedCount,
				totalShards: batch.totalShards,
				submittedShards: batch.submittedShards,
				runningShards: batch.runningShards,
				completedShards: batch.completedShards,
				failedShards: batch.failedShards,
				totalNodes: batch.totalNodes,
				completedNodes: batch.completedNodes,
				failedNodes: batch.failedNodes,
				cachedNodes: batch.cachedNodes,
				taintedNodes: batch.taintedNodes,
				failureSummary: batch.message,
				liveAvailable: false,
				historyOnly: true,
			});
			continue;
		}
		if (!item.run) continue;
		const run = item.run;
		const workflowName =
			(run.totalShards ?? 0) > 0
				? run.pipelineName || run.workflowName || run.id
				: run.workflowName || run.pipelineName || run.id;
		const liveAvailable = hasLiveWorkflowOperations(run.status);
		rows.push({
			kind: "run",
			key: run.id || workflowName,
			name: workflowName,
			status: run.status,
			nodeCount: run.nodeCount,
			assetCount: run.assetCount,
			assetIds: run.assetIds,
			createdAt: run.createdAt,
			finishedAt: run.finishedAt,
			totalEstimatedCost: run.totalEstimatedCost ?? null,
			runId: run.id,
			templateId: run.templateId,
			templateName: run.templateName || run.pipelineName,
			templateVersion: run.templateVersion ?? undefined,
			triggerSource:
				(run.totalShards ?? 0) > 0 && run.triggerSource === "backfill"
					? undefined
					: run.triggerSource,
			totalShards: run.totalShards,
			submittedShards: run.submittedShards,
			runningShards: run.runningShards,
			completedShards: run.completedShards,
			failedShards: run.failedShards,
			totalNodes: run.totalNodes,
			completedNodes: run.completedNodes,
			failedNodes: run.failedNodes,
			cachedNodes: run.cachedNodes,
			taintedNodes: run.taintedNodes,
			resourcePool: run.resourcePool,
			queueName: run.queueName,
			priority: run.priority,
			failureSummary: run.message || undefined,
			liveAvailable,
			historyOnly: !liveAvailable,
		});
	}

	rows.sort((a, b) => {
		const left = new Date(a.createdAt).getTime();
		const right = new Date(b.createdAt).getTime();
		return right - left;
	});
	return rows;
};

const filterExecutionRows = (
	rows: ExecutionListRow[],
	params: {
		status?: string;
		name?: string;
		label?: string[];
		createdAfter?: string;
		finishedBefore?: string;
	},
) => {
	const status = params.status?.trim();
	const name = normalizeSearchValue(params.name || "");
	const createdAfter = params.createdAfter
		? new Date(params.createdAfter)
		: null;
	const finishedBefore = params.finishedBefore
		? new Date(params.finishedBefore)
		: null;

	return rows.filter((row) => {
		if (status && row.status !== status) return false;
		if (name && !row.name.toLowerCase().includes(name)) {
			const templateName = (row.templateName || "").toLowerCase();
			if (!templateName.includes(name)) return false;
		}
		if (createdAfter && new Date(row.createdAt) < createdAfter) return false;
		if (finishedBefore) {
			if (!row.finishedAt) return false;
			if (new Date(row.finishedAt) > finishedBefore) return false;
		}
		if (params.label && params.label.length > 0) {
			const rowLabels = new Set(
				getDisplayLabelEntries(row.labels).map(([key, value]) =>
					serializeWorkflowLabel(key, value),
				),
			);
			for (const label of params.label) {
				if (!rowLabels.has(label)) return false;
			}
		}
		return true;
	});
};

export function WorkflowExecutionList({
	active = true,
	title = "流水线执行记录",
	emptyDescription = "暂无执行记录，部署流水线后将自动生成",
}: WorkflowExecutionListProps) {
	const [searchParams, setSearchParams] = useSearchParams();
	const [items, setItems] = useState<ExecutionListRow[]>([]);
	const [loading, setLoading] = useState(false);
	const [initializedOnce, setInitializedOnce] = useState(false);
	const [error, setError] = useState<WorkflowErrorState | null>(null);
	const [statusFilter, setStatusFilter] = useState<string | undefined>(
		normalizeStatus(searchParams.get("status")),
	);
	const [draftStatusFilter, setDraftStatusFilter] = useState<
		string | undefined
	>(normalizeStatus(searchParams.get("status")));
	const [nameSearch, setNameSearch] = useState(
		searchParams.get("name")?.trim() ?? "",
	);
	const [draftNameSearch, setDraftNameSearch] = useState(
		searchParams.get("name")?.trim() ?? "",
	);
	const [labelFilter, setLabelFilter] = useState<string[]>(() => {
		const labels = searchParams.getAll("label");
		return Array.from(
			new Set(labels.map((label) => label.trim()).filter(Boolean)),
		);
	});
	const [draftLabelFilter, setDraftLabelFilter] = useState<string[]>(() => {
		const labels = searchParams.getAll("label");
		return Array.from(
			new Set(labels.map((label) => label.trim()).filter(Boolean)),
		);
	});
	const [dateRange, setDateRange] = useState<[Dayjs | null, Dayjs | null]>([
		parseDate(searchParams.get("createdAfter")),
		parseDate(searchParams.get("finishedBefore")),
	]);
	const [draftDateRange, setDraftDateRange] = useState<
		[Dayjs | null, Dayjs | null]
	>([
		parseDate(searchParams.get("createdAfter")),
		parseDate(searchParams.get("finishedBefore")),
	]);
	const [operationLoading, setOperationLoading] = useState<string | null>(null);
	const [selectedRowKeys, setSelectedRowKeys] = useState<string[]>([]);
	const [bulkDeleteOpen, setBulkDeleteOpen] = useState(false);
	const [bulkDeleting, setBulkDeleting] = useState(false);
	const [pendingOperation, setPendingOperation] = useState<{
		record: ExecutionListRow;
		operation: WorkflowOperationConfig;
	} | null>(null);
	const [page, setPage] = useState(1);
	const [pageSize, setPageSize] = useState(20);
	const [totalItems, setTotalItems] = useState(0);
	const [openDropdown, setOpenDropdown] = useState<string | null>(null);
	const navigate = useNavigate();

	useEffect(() => {
		const nextStatus = normalizeStatus(searchParams.get("status"));
		const nextName = searchParams.get("name")?.trim() ?? "";
		const nextLabelFilter = Array.from(
			new Set(
				searchParams
					.getAll("label")
					.map((label) => label.trim())
					.filter(Boolean),
			),
		);
		const nextCreatedAfter = parseDate(searchParams.get("createdAfter"));
		const nextFinishedBefore = parseDate(searchParams.get("finishedBefore"));

		setStatusFilter((prev) => (prev === nextStatus ? prev : nextStatus));
		setDraftStatusFilter((prev) => (prev === nextStatus ? prev : nextStatus));
		setNameSearch((prev) => (prev === nextName ? prev : nextName));
		setDraftNameSearch((prev) => (prev === nextName ? prev : nextName));
		setLabelFilter((prev) =>
			arraysEqual(prev, nextLabelFilter) ? prev : nextLabelFilter,
		);
		setDraftLabelFilter((prev) =>
			arraysEqual(prev, nextLabelFilter) ? prev : nextLabelFilter,
		);
		setDateRange((prev) => {
			if (
				datesEqual(prev[0], nextCreatedAfter) &&
				datesEqual(prev[1], nextFinishedBefore)
			) {
				return prev;
			}
			return [nextCreatedAfter, nextFinishedBefore];
		});
		setDraftDateRange((prev) => {
			if (
				datesEqual(prev[0], nextCreatedAfter) &&
				datesEqual(prev[1], nextFinishedBefore)
			) {
				return prev;
			}
			return [nextCreatedAfter, nextFinishedBefore];
		});
	}, [searchParams]);

	const syncAppliedFiltersToUrl = useCallback(() => {
		const next = new URLSearchParams(searchParams);
		if (statusFilter) next.set("status", statusFilter);
		else next.delete("status");
		if (nameSearch) next.set("name", nameSearch.trim());
		else next.delete("name");
		next.delete("label");
		for (const label of labelFilter) {
			if (label) next.append("label", label);
		}
		if (dateRange[0]) next.set("createdAfter", dateRange[0].toISOString());
		else next.delete("createdAfter");
		if (dateRange[1]) next.set("finishedBefore", dateRange[1].toISOString());
		else next.delete("finishedBefore");

		if (next.toString() !== searchParams.toString()) {
			setSearchParams(next, { replace: true });
		}
	}, [
		dateRange,
		labelFilter,
		nameSearch,
		searchParams,
		setSearchParams,
		statusFilter,
	]);

	const refresh = useCallback(async () => {
		setLoading(true);
		setError(null);
		try {
			const params = {
				status: statusFilter,
				name: normalizeSearchValue(nameSearch) || undefined,
				label: labelFilter.length ? labelFilter : undefined,
				createdAfter: dateRange[0]?.toISOString(),
				finishedBefore: dateRange[1]?.toISOString(),
			};
			const runList = await listPipelineExecutions({
				limit: pageSize,
				offset: (page - 1) * pageSize,
				status: params.status,
				name: params.name,
				createdAfter: params.createdAfter,
				finishedBefore: params.finishedBefore,
			});
			const runs = (runList.items || []).filter(
				(item) =>
					!(
						item.kind === "run" &&
						(item.run?.parentRunId ||
							item.run?.batchRunId ||
							looksLikeShardChildRun(item.run))
					),
			);
			const hiddenRows = (runList.items || []).length - runs.length;
			const merged = buildExecutionRows(runs);
			const filtered = filterExecutionRows(merged, params);
			setTotalItems(
				params.label || hiddenRows > 0 ? filtered.length : runList.total || 0,
			);
			setItems(filtered);
			setSelectedRowKeys((prev) =>
				prev.filter((key) => filtered.some((item) => item.key === key)),
			);
		} catch (err) {
			console.error(err);
			setError(describeWorkflowError(err));
			setItems([]);
		} finally {
			setLoading(false);
			setInitializedOnce(true);
		}
	}, [statusFilter, nameSearch, labelFilter, dateRange, page, pageSize]);

	useEffect(() => {
		if (active) {
			refresh();
		}
	}, [active, refresh]);

	useEffect(() => {
		setPage(1);
		syncAppliedFiltersToUrl();
	}, [syncAppliedFiltersToUrl]);

	useEffect(() => {
		const timer = window.setTimeout(() => {
			const nextName = draftNameSearch.trim();
			if (nextName !== nameSearch) {
				setNameSearch(nextName);
				setPage(1);
			}
		}, 400);
		return () => window.clearTimeout(timer);
	}, [draftNameSearch, nameSearch]);

	const filtersDirty =
		draftStatusFilter !== statusFilter ||
		draftNameSearch !== nameSearch ||
		!arraysEqual(draftLabelFilter, labelFilter) ||
		!datesEqual(draftDateRange[0], dateRange[0]) ||
		!datesEqual(draftDateRange[1], dateRange[1]);

	const applyFilters = useCallback(() => {
		setStatusFilter(draftStatusFilter);
		setNameSearch(draftNameSearch.trim());
		setLabelFilter(draftLabelFilter);
		setDateRange(draftDateRange);
		setPage(1);
	}, [draftDateRange, draftLabelFilter, draftNameSearch, draftStatusFilter]);

	const resetFilters = useCallback(() => {
		setDraftStatusFilter(undefined);
		setDraftNameSearch("");
		setDraftLabelFilter([]);
		setDraftDateRange([null, null]);
		setStatusFilter(undefined);
		setNameSearch("");
		setLabelFilter([]);
		setDateRange([null, null]);
		setPage(1);
	}, []);

	const labelCheckboxOptions = useMemo(() => {
		const labels = new Set<string>();
		for (const item of items) {
			for (const [key, value] of getDisplayLabelEntries(item.labels)) {
				labels.add(serializeWorkflowLabel(key, value));
			}
		}
		const availableLabelOptions = Array.from(labels).sort((a, b) =>
			a.localeCompare(b),
		);
		return availableLabelOptions.map((label) => ({
			label: (() => {
				const separatorIndex = label.indexOf("=");
				const key =
					separatorIndex >= 0 ? label.slice(0, separatorIndex) : label;
				const value =
					separatorIndex >= 0 ? label.slice(separatorIndex + 1) : "";
				return (
					<Tag>
						{formatWorkflowLabelKey(key)}
						{value ? ` · ${value}` : ""}
					</Tag>
				);
			})(),
			value: label,
		}));
	}, [items]);

	const selectableRows = useMemo(
		() => items.filter((item) => canDeleteExecutionRecord(item)),
		[items],
	);
	const selectableRowKeys = useMemo(
		() => new Set(selectableRows.map((item) => item.key)),
		[selectableRows],
	);
	const allSelectableRowsSelected =
		selectableRows.length > 0 &&
		selectableRows.every((item) => selectedRowKeys.includes(item.key));
	const someSelectableRowsSelected =
		selectableRows.some((item) => selectedRowKeys.includes(item.key)) &&
		!allSelectableRowsSelected;

	const setPageRowsSelected = useCallback(
		(checked: boolean) => {
			setSelectedRowKeys((prev) => {
				if (checked) {
					const next = new Set(prev);
					for (const item of selectableRows) next.add(item.key);
					return Array.from(next);
				}
				return prev.filter((key) => !selectableRowKeys.has(key));
			});
		},
		[selectableRowKeys, selectableRows],
	);

	const setRowSelected = useCallback(
		(record: ExecutionListRow, checked: boolean) => {
			if (!canDeleteExecutionRecord(record)) return;
			setSelectedRowKeys((prev) => {
				if (checked) {
					return prev.includes(record.key) ? prev : [...prev, record.key];
				}
				return prev.filter((key) => key !== record.key);
			});
		},
		[],
	);

	const selectedRows = useMemo(
		() => items.filter((item) => selectedRowKeys.includes(item.key)),
		[items, selectedRowKeys],
	);
	const selectedDeletableRows = useMemo(
		() => selectedRows.filter((item) => canDeleteExecutionRecord(item)),
		[selectedRows],
	);
	const executionSummary = useMemo(() => {
		const counts = new Map<string, number>();
		for (const item of items) {
			counts.set(item.status, (counts.get(item.status) || 0) + 1);
		}
		return Array.from(counts.entries()).sort((a, b) =>
			a[0].localeCompare(b[0]),
		);
	}, [items]);
	const hasAppliedFilters = Boolean(
		statusFilter ||
			nameSearch ||
			labelFilter.length > 0 ||
			dateRange[0] ||
			dateRange[1],
	);

	const executeOperation = useCallback(
		async (
			record: ExecutionListRow,
			operation: WorkflowOperationConfig,
		): Promise<void> => {
			const loadingKey = `${record.name}:${operation.key}`;
			setOperationLoading(loadingKey);
			try {
				await operation.run();
				message.success(`${operation.title}已提交`);
				await refresh();
			} catch (err) {
				message.error(`${operation.title}失败: ${String(err)}`);
			} finally {
				setOperationLoading(null);
			}
		},
		[refresh],
	);

	const runOperation = useCallback(
		(record: ExecutionListRow, key: WorkflowOperationKey) => {
			const operation = getExecutionOperationConfig(record, key);
			if (!operation) return;

			if (
				operation.key === "delete" ||
				operation.key === "terminate" ||
				operation.key === "resubmit" ||
				operation.key === "retry"
			) {
				setPendingOperation({ record, operation });
				return;
			}

			void executeOperation(record, operation);
		},
		[executeOperation],
	);

	const confirmPendingOperation = useCallback(async () => {
		if (!pendingOperation) return;
		const { record, operation } = pendingOperation;
		setPendingOperation(null);
		await executeOperation(record, operation);
	}, [executeOperation, pendingOperation]);

	const confirmBulkDelete = useCallback(async () => {
		if (selectedDeletableRows.length === 0) return;
		setBulkDeleting(true);
		try {
			const results = await Promise.allSettled(
				selectedDeletableRows.map((row) =>
					row.liveAvailable
						? deleteWorkflow(row.name)
						: deletePipelineRun(row.runId ?? row.name),
				),
			);
			const failedCount = results.filter(
				(result) => result.status === "rejected",
			).length;
			const deletedCount = results.length - failedCount;
			if (deletedCount > 0)
				message.success(`已删除 ${deletedCount} 条执行记录`);
			if (failedCount > 0) message.error(`${failedCount} 条执行记录删除失败`);
			setSelectedRowKeys([]);
			setBulkDeleteOpen(false);
			await refresh();
		} finally {
			setBulkDeleting(false);
		}
	}, [refresh, selectedDeletableRows]);

	const columns: ExecutionColumn[] = [
		{
			title: "任务",
			dataIndex: "name",
			key: "name",
			width: 280,
			render: (_: unknown, record: ExecutionListRow) => {
				const name = record.name;
				const displayId = toAssetStyleId(
					record.batchRunId
						? `batch:${record.batchRunId}`
						: record.runId
							? record.runId
							: name,
				);
				const copyId = record.batchRunId ?? record.runId ?? name;
				const triggerLabel = formatTriggerSource(record.triggerSource);
				const secondaryLabel =
					record.kind === "batch"
						? `批量任务 ID: ${record.batchRunId}`
						: `Pipeline Run: ${record.name}`;
				const idTooltip = record.runId
					? `完整任务 ID: ${record.runId}`
					: copyId;
				return (
					<div className="pipeline-execution-cell-stack">
						<span className="pipeline-execution-primary-text" title={name}>
							{name}
						</span>
						<span
							className="pipeline-execution-secondary-text"
							title={secondaryLabel}
						>
							{secondaryLabel}
						</span>
						<div
							className="pipeline-execution-copy-line pipeline-execution-copy-line--secondary"
							title={idTooltip}
						>
							<span className="pipeline-execution-copy-line__text">
								ID: {displayId}
							</span>
							<Tooltip title="复制执行 ID">
								<button
									type="button"
									className="link-like-button pipeline-execution-copy-button"
									aria-label={`复制执行 ID ${copyId}`}
									onClick={(event) => {
										event.stopPropagation();
										void copyExecutionText(copyId, "执行 ID");
									}}
								>
									<CopyOutlined />
								</button>
							</Tooltip>
						</div>
						{record.kind === "batch" ? (
							<Space size={[6, 6]} wrap style={{ marginTop: 4 }}>
								<Tag color="blue">批量任务</Tag>
								{typeof record.succeededCount === "number" ? (
									<Tag color="green">成功 {record.succeededCount}</Tag>
								) : null}
								{typeof record.runningCount === "number" ? (
									<Tag color="processing">运行 {record.runningCount}</Tag>
								) : null}
								{typeof record.pendingCount === "number" ? (
									<Tag color="processing">待调度 {record.pendingCount}</Tag>
								) : null}
								{typeof record.failedCount === "number" ? (
									<Tag color="red">失败 {record.failedCount}</Tag>
								) : null}
							</Space>
						) : null}
						{(record.totalShards ?? 0) > 0 && record.kind !== "batch" ? (
							<Space size={[6, 6]} wrap style={{ marginTop: 4 }}>
								<Tag color="blue">批量任务</Tag>
							</Space>
						) : null}
						<Space size={[6, 6]} wrap style={{ marginTop: 4 }}>
							{triggerLabel ? <Tag color="gold">{triggerLabel}</Tag> : null}
							{record.historyOnly && !LIVE_STATUS_FILTERS.has(record.status) ? (
								<Tooltip title="Argo 工作流已被 TTL 清理，仅保留运行记录">
									<Tag>历史记录</Tag>
								</Tooltip>
							) : null}
						</Space>
					</div>
				);
			},
		},
		{
			title: "流水线",
			key: "pipeline",
			width: 240,
			render: (_: unknown, record: ExecutionListRow) =>
				renderPipelineIdentity(record),
		},
		{
			title: "状态",
			dataIndex: "status",
			key: "status",
			width: 130,
			render: (_: unknown, record: ExecutionListRow) => {
				const status = record.status;
				return (
					<Tag
						color={
							STATUS_COLORS[status] || STATUS_ACCENT_COLORS[status] || "default"
						}
						style={{ padding: "2px 8px" }}
					>
						{status}
					</Tag>
				);
			},
		},
		{
			title: "资产",
			key: "assetCount",
			width: 100,
			render: (_: unknown, record: ExecutionListRow) =>
				renderCompactMetric(getDisplayAssetMetric(record), "资产"),
		},
		{
			title: "节点",
			dataIndex: "nodeCount",
			key: "nodes",
			width: 120,
			render: (_: unknown, record: ExecutionListRow) => {
				const cached = record.cachedNodes ?? 0;
				return renderCompactMetric(
					getDisplayNodeMetric(record),
					cached > 0 ? `缓存 ${cached}` : "节点",
				);
			},
		},
		{
			title: "失败",
			key: "failures",
			width: 180,
			render: (_: unknown, record: ExecutionListRow) =>
				renderFailureMetric(record),
		},
		{
			title: "资源",
			key: "resources",
			width: 140,
			render: (_: unknown, record: ExecutionListRow) =>
				renderResourcePriority(record),
		},
		{
			title: "耗时",
			key: "duration",
			width: 140,
			render: (_: unknown, record: ExecutionListRow) => (
				<DurationPanel
					phase={record.status}
					startedAt={record.createdAt}
					finishedAt={record.finishedAt}
				/>
			),
		},
		{
			title: "创建时间",
			dataIndex: "createdAt",
			key: "createdAt",
			width: 220,
			render: (_: unknown, record: ExecutionListRow) =>
				renderTimestamp(record.createdAt),
		},
		{
			title: "完成时间",
			dataIndex: "finishedAt",
			key: "finishedAt",
			width: 220,
			render: (_: unknown, record: ExecutionListRow) =>
				renderTimestamp(record.finishedAt),
		},
		{
			title: "操作",
			key: "actions",
			width: 128,
			render: (_: unknown, record: ExecutionListRow) => {
				const operationConfigs =
					record.kind === "batch"
						? []
						: record.liveAvailable
							? getAvailableWorkflowOperationConfigs(record)
							: record.runId
								? [ARCHIVED_RUN_RETRY_OPERATION, ARCHIVED_RUN_DELETE_OPERATION]
								: [];
				const menuItems = operationConfigs.map((operation) => ({
					key: operation.key,
					label: operation.title,
					icon: operation.icon,
					danger: operation.danger,
				}));
				const hasOperationLoading = operationLoading?.startsWith(
					`${record.name}:`,
				);
				const detailHref = buildWorkflowExecutionUrl(
					record.name,
					record.runId ?? record.batchRunId,
				);
				const failed = isFailedExecutionStatus(record.status);
				const running = LIVE_STATUS_FILTERS.has(record.status);

				return (
					<div className="pipeline-execution-actions">
						<Button
							type="link"
							size="small"
							danger={failed}
							onClick={(event) => {
								event.stopPropagation();
								navigate(detailHref);
							}}
						>
							{failed ? "失败详情" : running ? "查看实时" : "查看详情"}
						</Button>
						<Dropdown
							open={openDropdown === record.name}
							onOpenChange={(open) =>
								setOpenDropdown(open ? record.name : null)
							}
							menu={{
								items: menuItems,
								onClick: ({ key, domEvent }) => {
									domEvent.stopPropagation();
									setOpenDropdown(null);
									runOperation(record, key as WorkflowOperationKey);
								},
							}}
							trigger={["click"]}
						>
							<Button
								size="small"
								icon={<MoreOutlined />}
								loading={hasOperationLoading}
								aria-label="更多操作"
								onClick={(event) => {
									event.stopPropagation();
									if (menuItems.length === 0) {
										message.info(
											record.historyOnly
												? "该记录已归档，且没有关联的 DataBrew Run ID，暂无可用运行操作"
												: "当前状态暂无可用操作",
										);
									}
								}}
							/>
						</Dropdown>
					</div>
				);
			},
		},
	];

	const showSkeleton = loading && !initializedOnce;

	return (
		<div className="pipeline-execution-list">
			<div
				style={{
					display: "flex",
					alignItems: "center",
					gap: 12,
					marginBottom: 16,
				}}
			>
				<Typography.Title level={4} style={{ margin: 0 }}>
					{title}
				</Typography.Title>
				<Tooltip
					title={
						selectedRowKeys.length === 0
							? "请先选择执行记录"
							: selectedDeletableRows.length === 0
								? "当前选中项没有可删除的执行记录"
								: undefined
					}
				>
					<span>
						<Button
							danger
							disabled={selectedDeletableRows.length === 0}
							onClick={() => setBulkDeleteOpen(true)}
						>
							批量删除
							{selectedDeletableRows.length > 0
								? `（${selectedDeletableRows.length}）`
								: ""}
						</Button>
					</span>
				</Tooltip>
				<Button icon={<ReloadOutlined />} onClick={refresh} loading={loading}>
					刷新
				</Button>
			</div>

			{items.length > 0 ? (
				<div
					style={{
						display: "flex",
						flexWrap: "wrap",
						gap: 8,
						marginBottom: 16,
					}}
				>
					<Tag>当前筛选共 {totalItems} 条</Tag>
					<Tag>已加载 {items.length} 条</Tag>
					{executionSummary.map(([status, count]) => (
						<Tag
							key={status}
							color={
								STATUS_COLORS[status] ||
								STATUS_ACCENT_COLORS[status] ||
								"default"
							}
						>
							{status} {count}
						</Tag>
					))}
					<Typography.Text type="secondary" style={{ fontSize: 12 }}>
						状态统计基于已加载结果
					</Typography.Text>
				</div>
			) : null}

			<div className="pipeline-execution-filters" style={{ gap: 8 }}>
				<Select
					id="workflow-execution-status-filter"
					allowClear
					placeholder="状态筛选"
					style={{ minWidth: 140, flex: "1 1 160px" }}
					value={draftStatusFilter}
					onChange={(val) => setDraftStatusFilter(val)}
					options={WORKFLOW_PHASES.map((status) => ({
						label: status,
						value: status,
					}))}
				/>
				<Input.Search
					id="workflow-execution-name-search"
					name="workflowExecutionName"
					allowClear
					placeholder="按名称搜索"
					style={{ minWidth: 220, flex: "1 1 220px" }}
					value={draftNameSearch}
					onChange={(event) => setDraftNameSearch(event.target.value)}
					onSearch={applyFilters}
				/>
				<RangePicker
					id={{
						start: "workflow-execution-start-date",
						end: "workflow-execution-end-date",
					}}
					value={draftDateRange}
					placeholder={["创建开始时间", "完成截止时间"]}
					onChange={(values) =>
						setDraftDateRange([values?.[0] ?? null, values?.[1] ?? null])
					}
					style={{ minWidth: 320, flex: "1 1 260px" }}
				/>
				<Button type="primary" onClick={applyFilters} disabled={!filtersDirty}>
					应用
				</Button>
				<Button onClick={resetFilters}>重置</Button>
			</div>

			{labelCheckboxOptions.length > 0 ? (
				<div
					style={{
						display: "flex",
						alignItems: "center",
						flexWrap: "wrap",
						gap: 8,
						marginBottom: 16,
					}}
				>
					<Typography.Text type="secondary">标签筛选：</Typography.Text>
					<Checkbox.Group
						options={labelCheckboxOptions}
						value={draftLabelFilter}
						onChange={(values) => setDraftLabelFilter(values as string[])}
					/>
				</div>
			) : null}

			{error ? (
				<Alert
					type="error"
					showIcon
					message={getErrorTitle(error.kind)}
					description={error.message}
					action={
						<Button size="small" onClick={refresh} loading={loading}>
							重试
						</Button>
					}
					style={{ marginBottom: 16 }}
				/>
			) : null}

			{showSkeleton ? (
				<Skeleton
					active
					paragraph={{ rows: 8 }}
					title={false}
					style={{ width: "100%" }}
				/>
			) : !error && items.length === 0 ? (
				<Empty
					description={
						hasAppliedFilters
							? "没有符合当前筛选条件的 Pipeline Run"
							: emptyDescription
					}
				>
					{hasAppliedFilters ? (
						<Button size="small" onClick={resetFilters}>
							清空筛选
						</Button>
					) : (
						<Typography.Text type="secondary">
							可以从「流水线」页选择模板并提交一次运行。
						</Typography.Text>
					)}
				</Empty>
			) : (
				<div className="pipeline-execution-table">
					<div className="pipeline-execution-table-scroll">
						<table className="pipeline-execution-native-table">
							<colgroup>
								<col style={{ width: 52 }} />
								{columns.map((column) => (
									<col key={column.key} style={{ width: column.width }} />
								))}
							</colgroup>
							<thead>
								<tr>
									<th className="pipeline-execution-selection-cell">
										<Checkbox
											aria-label="选择当前页可删除执行记录"
											checked={allSelectableRowsSelected}
											disabled={selectableRows.length === 0}
											indeterminate={someSelectableRowsSelected}
											onChange={(event) =>
												setPageRowsSelected(event.target.checked)
											}
										/>
									</th>
									{columns.map((column) => (
										<th key={column.key}>{column.title}</th>
									))}
								</tr>
							</thead>
							<tbody>
								{items.map((record) => (
									<tr
										key={record.key}
										className="pipeline-execution-table-row"
										onClick={(event) => {
											const el = event.target as HTMLElement;
											if (
												el.closest(
													"a, button, input, textarea, select, label, [role='checkbox'], .ant-pagination, .ant-pagination-item, .ant-dropdown",
												)
											) {
												return;
											}
											navigate(
												buildWorkflowExecutionUrl(
													record.name,
													record.runId ?? record.batchRunId,
												),
											);
										}}
									>
										<td className="pipeline-execution-selection-cell">
											<Checkbox
												aria-label={`选择 ${record.name}`}
												checked={selectedRowKeys.includes(record.key)}
												disabled={!canDeleteExecutionRecord(record)}
												title={
													canDeleteExecutionRecord(record)
														? undefined
														: "该记录没有可删除的执行 ID"
												}
												onClick={(event) => event.stopPropagation()}
												onChange={(event) =>
													setRowSelected(record, event.target.checked)
												}
											/>
										</td>
										{columns.map((column) => {
											const value = column.dataIndex
												? record[column.dataIndex]
												: undefined;
											return (
												<td key={column.key}>
													{column.render
														? column.render(value, record)
														: String(value ?? "")}
												</td>
											);
										})}
									</tr>
								))}
							</tbody>
						</table>
					</div>
					<div className="pipeline-execution-pagination">
						<Pagination
							current={page}
							pageSize={pageSize}
							total={totalItems}
							showSizeChanger
							showQuickJumper
							pageSizeOptions={["10", "20", "50", "100"]}
							showTotal={(total, range) =>
								`第 ${range[0]}-${range[1]} 条 / 共 ${total} 条 · 共 ${Math.max(1, Math.ceil(total / pageSize))} 页`
							}
							onChange={(nextPage, nextPageSize) => {
								setPage(nextPage);
								setPageSize(nextPageSize);
							}}
						/>
					</div>
				</div>
			)}
			<Modal
				open={!!pendingOperation}
				title={
					pendingOperation
						? `确认${pendingOperation.operation.title} ${pendingOperation.record.name}?`
						: ""
				}
				okText={pendingOperation?.operation.title}
				cancelText="取消"
				okButtonProps={{ danger: pendingOperation?.operation.danger }}
				onOk={confirmPendingOperation}
				onCancel={() => setPendingOperation(null)}
			>
				{pendingOperation?.operation.key === "resubmit" ||
				pendingOperation?.operation.key === "retry" ? (
					<p>将基于当前工作流再次提交执行。</p>
				) : null}
			</Modal>
			<Modal
				open={bulkDeleteOpen}
				title={`删除选中的 ${selectedDeletableRows.length} 条执行记录？`}
				okText="删除"
				cancelText="取消"
				okButtonProps={{ danger: true, loading: bulkDeleting }}
				onOk={confirmBulkDelete}
				onCancel={() => setBulkDeleteOpen(false)}
			>
				<p>删除后不可恢复。正在运行的工作流请先确认不再需要。</p>
			</Modal>
		</div>
	);
}
