export type RunInputMode = "asset" | "video";

export function parseRunInputIds(raw: string | null | undefined): string[] {
	if (!raw) return [];
	return Array.from(
		new Set(
			raw
				.split(/[\n,]/)
				.map((item) => item.trim())
				.filter(Boolean),
		),
	);
}

export function getRunActionLabel(_mode: RunInputMode, _count: number): string {
	return "运行";
}

export function getRunInputSummary(
	mode: RunInputMode,
	count: number,
): { message: string; description?: string } {
	if (count > 0) {
		return {
			message: `将处理 ${count} 个${mode === "video" ? "视频" : "资产"}`,
		};
	}
	return {
		message: mode === "video" ? "本次不绑定视频" : "本次不绑定资产",
		description:
			mode === "video"
				? "本次运行不会注入视频输入，适合调试不依赖视频输入的流水线。"
				: "本次运行不会注入资产环境变量，适合调试不依赖资产输入的流水线。",
	};
}
