import type {
	Argument,
	InlineFile,
	Pipeline,
	PipelineEdgeDef,
	PipelineNodeData,
	PipelineNodeDef,
	PipelineNodePosition,
	Port,
	Toleration,
	VolumeMount,
} from "../components/pipeline/types";

/** Coerce API/canvas args (string[] or Argument[]) into transpiler Argument objects. */
export function normalizeComponentArgs(
	args: unknown[] | undefined,
): Argument[] {
	if (!args || args.length === 0) return [];
	return args.map((item, index) => {
		if (typeof item === "string") {
			const value = item.trim();
			return { name: value || `arg${index + 1}`, value };
		}
		if (item && typeof item === "object") {
			const record = item as { name?: string; value?: string; from?: string };
			const value = record.value ?? record.name ?? "";
			const name = record.name?.trim() || value || `arg${index + 1}`;
			return record.from ? { name, value, from: record.from } : { name, value };
		}
		return { name: `arg${index + 1}`, value: String(item) };
	});
}

function isShellBinary(value: string) {
	return [
		"sh",
		"bash",
		"dash",
		"zsh",
		"/bin/sh",
		"/bin/bash",
		"/usr/bin/sh",
		"/usr/bin/bash",
	].includes(value.trim());
}

export function normalizeShellCommandArgs(
	command: string[],
	args: Argument[],
): Argument[] {
	if (
		command.length !== 2 ||
		!isShellBinary(command[0]) ||
		command[1] !== "-c" ||
		args.length === 0
	) {
		return args;
	}
	const values = args.map((arg) => arg.value?.trim() || "");
	if (values.length >= 3 && isShellBinary(values[0]) && values[1] === "-c") {
		const last = args[args.length - 1];
		return [{ name: last.name || "script", value: last.value || "" }];
	}
	if (values.length >= 2 && values[0] === "-c") {
		const last = args[args.length - 1];
		return [{ name: last.name || "script", value: last.value || "" }];
	}
	return args;
}

function envToRecords(raw: unknown): Argument[] {
	if (!raw) return [];
	if (Array.isArray(raw)) {
		return raw
			.map((item): Argument | null => {
				if (!item || typeof item !== "object") return null;
				const record = item as { name?: string; value?: string; from?: string };
				if (!record.name) return null;
				return {
					name: record.name,
					value: record.value || "",
					...(record.from ? { from: record.from } : {}),
				};
			})
			.filter((item): item is Argument => Boolean(item));
	}
	if (typeof raw === "object") {
		return Object.entries(raw as Record<string, string>).map(
			([name, value]) => ({
				name,
				value: String(value || ""),
			}),
		);
	}
	return [];
}

function normalizeTolerations(value: unknown): Toleration[] {
	if (!Array.isArray(value)) return [];
	return value
		.flatMap((item) => {
			if (!item || typeof item !== "object") return [];
			const record = item as Record<string, unknown>;
			const key = typeof record.key === "string" ? record.key.trim() : "";
			const operator =
				typeof record.operator === "string" ? record.operator.trim() : "";
			const itemValue =
				typeof record.value === "string" ? record.value.trim() : "";
			const effect =
				typeof record.effect === "string" ? record.effect.trim() : "";
			const rawSeconds = record.tolerationSeconds;
			const tolerationSeconds =
				typeof rawSeconds === "number" && Number.isFinite(rawSeconds)
					? rawSeconds
					: typeof rawSeconds === "string" && rawSeconds.trim() !== ""
						? Number(rawSeconds)
						: undefined;
			if (
				!key &&
				!operator &&
				!itemValue &&
				!effect &&
				tolerationSeconds === undefined
			) {
				return null;
			}
			return {
				...(key ? { key } : {}),
				...(operator ? { operator } : {}),
				...(itemValue ? { value: itemValue } : {}),
				...(effect ? { effect } : {}),
				...(tolerationSeconds !== undefined &&
				Number.isFinite(tolerationSeconds)
					? { tolerationSeconds }
					: {}),
			};
		})
		.filter((item): item is Toleration => Boolean(item));
}

function normalizeVolumeMounts(value: unknown): VolumeMount[] {
	if (!Array.isArray(value)) return [];
	const mounts: VolumeMount[] = [];
	for (const item of value) {
		if (!item || typeof item !== "object") continue;
		const record = item as Record<string, unknown>;
		const name = typeof record.name === "string" ? record.name.trim() : "";
		const mountPath =
			typeof record.mountPath === "string" ? record.mountPath.trim() : "";
		const pvcName =
			typeof record.pvcName === "string" ? record.pvcName.trim() : "";
		const secretProviderClass =
			typeof record.secretProviderClass === "string" // pragma: allowlist secret
				? record.secretProviderClass.trim()
				: "";
		const csiDriver =
			typeof record.csiDriver === "string" ? record.csiDriver.trim() : "";
		const emptyDir = record.emptyDir === true;
		if (!name && !mountPath && !pvcName && !secretProviderClass && !emptyDir) {
			continue;
		}
		const type: VolumeMount["type"] =
			secretProviderClass || csiDriver ? "csi" : pvcName ? "pvc" : "emptyDir";
		const mount: VolumeMount = {
			type,
			name,
			mountPath,
			...(typeof record.subPath === "string" && record.subPath.trim()
				? { subPath: record.subPath.trim() }
				: {}),
			...(record.readOnly === true ? { readOnly: true } : {}),
			...(pvcName ? { pvcName } : {}),
			...(emptyDir || type === "emptyDir" ? { emptyDir: true } : {}),
			...(csiDriver ? { csiDriver } : {}),
			...(secretProviderClass ? { secretProviderClass } : {}),
		};
		mounts.push(mount);
	}
	return mounts;
}

function normalizeInlineFiles(value: unknown): InlineFile[] {
	if (!Array.isArray(value)) return [];
	return value.flatMap((item) => {
		if (!item || typeof item !== "object") return [];
		const record = item as Record<string, unknown>;
		const filePath = typeof record.path === "string" ? record.path.trim() : "";
		const content = typeof record.content === "string" ? record.content : "";
		if (!filePath && !content) return [];
		return [{ path: filePath, content }];
	});
}

const DEFAULT_INPUT_PORT = "input";
const DEFAULT_OUTPUT_PORT = "output";
const LEGACY_LAYOUT_START_X = 120;
const LEGACY_LAYOUT_START_Y = 100;
const LEGACY_LAYOUT_COLUMN_GAP = 340;
const LEGACY_LAYOUT_ROW_GAP = 170;

type PipelineCanvasNode = {
	id: string;
	type?: string;
	position: { x: number; y: number };
	data: PipelineNodeData;
};

type PipelineCanvasEdge = {
	id: string;
	source: string;
	target: string;
	sourceHandle?: string | null;
	targetHandle?: string | null;
};

const defaultInputs = (): Port[] => [
	{ name: DEFAULT_INPUT_PORT, type: "string" },
];
const defaultOutputs = (): Port[] => [
	{ name: DEFAULT_OUTPUT_PORT, type: "string" },
];

function normalizePorts(
	ports: Port[] | undefined,
	fallback: () => Port[],
): Port[] {
	if (!ports || ports.length === 0) return fallback();
	const seen = new Set<string>();
	const normalized: Port[] = [];
	for (const port of ports) {
		const name = port.name?.trim();
		if (!name || seen.has(name)) continue;
		seen.add(name);
		normalized.push({
			name,
			type: port.type?.trim() || "string",
			...(port.desc?.trim() ? { desc: port.desc.trim() } : {}),
			...(port.default_value?.trim()
				? { default_value: port.default_value.trim() }
				: {}),
		});
	}
	return normalized.length > 0 ? normalized : fallback();
}

/** Format React Flow edge endpoints for the transpiler (node-id.port-name). */
export function formatEdgeEndpoint(
	nodeId: string,
	handle: string | null | undefined,
	defaultPort: string,
): string {
	if (nodeId.includes(".")) {
		return nodeId;
	}
	const port = (handle && handle.length > 0 ? handle : defaultPort).replace(
		/^\./,
		"",
	);
	return `${nodeId}.${port}`;
}

export function toTranspilerPipeline(
	nodes: PipelineCanvasNode[],
	edges: PipelineCanvasEdge[],
	meta: { name: string; version?: string },
): Pipeline {
	return {
		name: meta.name,
		version: meta.version ?? "1",
		layout: {
			nodes: Object.fromEntries(
				nodes.map((node) => [
					node.id,
					{
						x: Math.round(node.position.x),
						y: Math.round(node.position.y),
					},
				]),
			),
		},
		nodes: nodes.map((n) => nodeToDef(n)),
		edges: edges.map((e) => edgeToDef(e)),
	};
}

function nodeToDef(n: PipelineCanvasNode): PipelineNodeDef {
	const d = n.data;
	return {
		id: n.id,
		component: {
			name: d.label || "",
			image: d.image || "",
			type: d.type || "container",
			source: d.source || "custom",
			command: d.command || [],
			args: normalizeShellCommandArgs(
				d.command || [],
				normalizeComponentArgs(d.args as unknown[]),
			),
			...(d.env && d.env.length > 0
				? { env: normalizeComponentArgs(d.env as unknown[]) }
				: {}),
			resources:
				d.cpu || d.memory || d.disk || d.gpu || d.computeTier
					? {
							cpu: d.cpu,
							memory: d.memory,
							disk: d.disk,
							gpu: d.gpu,
							computeTier: d.computeTier,
							type: d.type || "container",
							source: d.source || "custom",
						}
					: undefined,
			...(d.tolerations && d.tolerations.length > 0
				? { tolerations: normalizeTolerations(d.tolerations) }
				: {}),
		},
		inputs: normalizePorts(d.inputPorts, defaultInputs),
		outputs: normalizePorts(d.outputPorts, defaultOutputs),
		...(d.tolerations && d.tolerations.length > 0
			? { tolerations: normalizeTolerations(d.tolerations) }
			: {}),
		...(d.volumeMounts && d.volumeMounts.length > 0
			? { volume_mounts: normalizeVolumeMounts(d.volumeMounts) }
			: {}),
		...(d.inlineFiles && d.inlineFiles.length > 0
			? { inlineFiles: normalizeInlineFiles(d.inlineFiles) }
			: {}),
		...(d.defaultConfig
			? {
					defaultConfig: {
						command: d.defaultConfig.command || [],
						args: normalizeComponentArgs(d.defaultConfig.args as unknown[]),
						...(d.defaultConfig.source
							? { source: d.defaultConfig.source }
							: {}),
						env: normalizeComponentArgs(d.defaultConfig.env as unknown[]),
						...(d.defaultConfig.cpu ? { cpu: d.defaultConfig.cpu } : {}),
						...(d.defaultConfig.memory
							? { memory: d.defaultConfig.memory }
							: {}),
						...(d.defaultConfig.disk ? { disk: d.defaultConfig.disk } : {}),
						...(d.defaultConfig.gpu ? { gpu: d.defaultConfig.gpu } : {}),
						...(d.defaultConfig.computeTier
							? { computeTier: d.defaultConfig.computeTier }
							: {}),
						...(d.defaultConfig.tolerations &&
						d.defaultConfig.tolerations.length > 0
							? {
									tolerations: normalizeTolerations(
										d.defaultConfig.tolerations,
									),
								}
							: {}),
						...(d.defaultConfig.volumeMounts &&
						d.defaultConfig.volumeMounts.length > 0
							? {
									volumeMounts: normalizeVolumeMounts(
										d.defaultConfig.volumeMounts,
									),
								}
							: {}),
						...(d.defaultConfig.inlineFiles &&
						d.defaultConfig.inlineFiles.length > 0
							? {
									inlineFiles: normalizeInlineFiles(
										d.defaultConfig.inlineFiles,
									),
								}
							: {}),
					},
				}
			: {}),
	};
}

function edgeToDef(e: PipelineCanvasEdge): PipelineEdgeDef {
	return {
		source: formatEdgeEndpoint(e.source, e.sourceHandle, DEFAULT_OUTPUT_PORT),
		target: formatEdgeEndpoint(e.target, e.targetHandle, DEFAULT_INPUT_PORT),
	};
}

/** Restore canvas state from a saved transpiler pipeline JSON. */
export function fromTranspilerPipeline(pipeline: Pipeline): {
	nodes: PipelineCanvasNode[];
	edges: PipelineCanvasEdge[];
} {
	const fallbackLayout = buildLegacyDagLayout(pipeline);
	const nodes: PipelineCanvasNode[] = pipeline.nodes.map((pn, i) => ({
		id: pn.id,
		type: "pipelineStep" as const,
		position: normalizeNodePosition(pipeline.layout?.nodes?.[pn.id]) ??
			fallbackLayout[pn.id] ?? {
				x: LEGACY_LAYOUT_START_X + i * LEGACY_LAYOUT_COLUMN_GAP,
				y: LEGACY_LAYOUT_START_Y,
			},
		data: {
			label: pn.component.name,
			image: pn.component.image,
			type: (pn.component as { type?: string }).type || "container",
			source: (pn.component as { source?: string }).source || "custom",
			command: pn.component.command || [],
			args: normalizeComponentArgs(pn.component.args as unknown[]),
			env: envToRecords(
				pn.component.env ||
					(pn.component.resources as { env?: unknown } | undefined)?.env,
			),
			cpu: pn.component.resources?.cpu || "",
			memory: pn.component.resources?.memory || "",
			disk: pn.component.resources?.disk || "",
			gpu: pn.component.resources?.gpu || "",
			computeTier: pn.component.resources?.computeTier || "",
			tolerations: normalizeTolerations(
				pn.tolerations || pn.component.tolerations,
			),
			volumeMounts: normalizeVolumeMounts(pn.volume_mounts),
			inlineFiles: normalizeInlineFiles(pn.inlineFiles),
			inputPorts: normalizePorts(pn.inputs, defaultInputs),
			outputPorts: normalizePorts(pn.outputs, defaultOutputs),
			defaultConfig: pn.defaultConfig
				? {
						command: pn.defaultConfig.command || [],
						args: normalizeComponentArgs(pn.defaultConfig.args as unknown[]),
						...(pn.defaultConfig.source
							? { source: pn.defaultConfig.source }
							: {}),
						env: normalizeComponentArgs(pn.defaultConfig.env as unknown[]),
						...(pn.defaultConfig.cpu ? { cpu: pn.defaultConfig.cpu } : {}),
						...(pn.defaultConfig.memory
							? { memory: pn.defaultConfig.memory }
							: {}),
						...(pn.defaultConfig.disk ? { disk: pn.defaultConfig.disk } : {}),
						...(pn.defaultConfig.gpu ? { gpu: pn.defaultConfig.gpu } : {}),
						...(pn.defaultConfig.computeTier
							? { computeTier: pn.defaultConfig.computeTier }
							: {}),
						...(pn.defaultConfig.tolerations &&
						pn.defaultConfig.tolerations.length > 0
							? {
									tolerations: normalizeTolerations(
										pn.defaultConfig.tolerations,
									),
								}
							: {}),
						...(pn.defaultConfig.volumeMounts &&
						pn.defaultConfig.volumeMounts.length > 0
							? {
									volumeMounts: normalizeVolumeMounts(
										pn.defaultConfig.volumeMounts,
									),
								}
							: {}),
						...(pn.defaultConfig.inlineFiles &&
						pn.defaultConfig.inlineFiles.length > 0
							? {
									inlineFiles: normalizeInlineFiles(
										pn.defaultConfig.inlineFiles,
									),
								}
							: {}),
					}
				: undefined,
		},
	}));

	const edges: PipelineCanvasEdge[] = pipeline.edges.map((pe, i) => {
		const source = splitRef(pe.source);
		const target = splitRef(pe.target);
		return {
			id: `e-${i}`,
			source: source.nodeId,
			target: target.nodeId,
			...(source.port ? { sourceHandle: source.port } : {}),
			...(target.port ? { targetHandle: target.port } : {}),
		};
	});

	return { nodes, edges };
}

function normalizeNodePosition(
	position: PipelineNodePosition | undefined,
): PipelineNodePosition | undefined {
	if (!position) return undefined;
	const { x, y } = position;
	if (!Number.isFinite(x) || !Number.isFinite(y)) return undefined;
	return { x, y };
}

function buildLegacyDagLayout(
	pipeline: Pipeline,
): Record<string, PipelineNodePosition> {
	const nodeIds = pipeline.nodes.map((node) => node.id);
	const nodeIdSet = new Set(nodeIds);
	const incoming = new Map<string, Set<string>>();
	const outgoing = new Map<string, Set<string>>();
	for (const id of nodeIds) {
		incoming.set(id, new Set());
		outgoing.set(id, new Set());
	}
	for (const edge of pipeline.edges || []) {
		const source = splitRef(edge.source).nodeId;
		const target = splitRef(edge.target).nodeId;
		if (!nodeIdSet.has(source) || !nodeIdSet.has(target)) continue;
		outgoing.get(source)?.add(target);
		incoming.get(target)?.add(source);
	}

	const levels = new Map<string, number>();
	const queue = nodeIds.filter((id) => (incoming.get(id)?.size ?? 0) === 0);
	for (const id of queue) {
		levels.set(id, 0);
	}

	let cursor = 0;
	while (cursor < queue.length) {
		const id = queue[cursor++];
		const nextLevel = (levels.get(id) ?? 0) + 1;
		for (const target of outgoing.get(id) ?? []) {
			const previous = levels.get(target);
			if (previous === undefined || nextLevel > previous) {
				levels.set(target, nextLevel);
			}
			const parents = incoming.get(target) ?? new Set();
			const allParentsAssigned = Array.from(parents).every((parent) =>
				levels.has(parent),
			);
			if (allParentsAssigned && !queue.includes(target)) {
				queue.push(target);
			}
		}
	}

	for (const id of nodeIds) {
		if (!levels.has(id)) {
			levels.set(id, 0);
		}
	}

	const columns = new Map<number, string[]>();
	for (const id of nodeIds) {
		const level = levels.get(id) ?? 0;
		const column = columns.get(level) ?? [];
		column.push(id);
		columns.set(level, column);
	}

	const positions: Record<string, PipelineNodePosition> = {};
	for (const [level, ids] of columns) {
		const columnHeight = (ids.length - 1) * LEGACY_LAYOUT_ROW_GAP;
		ids.forEach((id, index) => {
			positions[id] = {
				x: LEGACY_LAYOUT_START_X + level * LEGACY_LAYOUT_COLUMN_GAP,
				y:
					LEGACY_LAYOUT_START_Y +
					index * LEGACY_LAYOUT_ROW_GAP -
					columnHeight / 2,
			};
		});
	}
	return positions;
}

function splitRef(ref: string): { nodeId: string; port?: string } {
	const dot = ref.lastIndexOf(".");
	if (dot < 0) {
		return { nodeId: ref };
	}
	return { nodeId: ref.slice(0, dot), port: ref.slice(dot + 1) };
}
