import { MinusCircleOutlined, PlusOutlined } from "@ant-design/icons";
import type { Node } from "@ant-design/pro-flow";
import {
	Alert,
	Button,
	Checkbox,
	Form,
	Input,
	Modal,
	Select,
	Space,
	Tag,
	Tooltip,
	Typography,
} from "antd";
import { useEffect } from "react";
import {
	buildResourceSummaryFromValues,
	buildResourceValues,
	type ComputeProfileId,
	computeProfileOptions,
	getComputeProfileById,
	inferComputeProfile,
} from "../../lib/computeResourceProfiles";
import { resourceQuantityRule } from "../../lib/pipelineResourceValidation";
import type {
	Argument,
	InlineFile,
	NodeDefaultConfig,
	PipelineNodeData,
	Toleration,
	VolumeMount,
} from "./types";

interface NodeConfigPanelProps {
	open: boolean;
	node: Node<PipelineNodeData>;
	onCancel: () => void;
	onSave: (id: string, data: Partial<PipelineNodeData>) => void;
}

type EnvFormItem = { name?: string; value?: string };
type TolerationFormItem = {
	key?: string;
	operator?: string;
	value?: string;
	effect?: string;
	tolerationSeconds?: string;
};
type VolumeMountFormItem = {
	type?: "csi" | "pvc" | "emptyDir";
	name?: string;
	mountPath?: string;
	subPath?: string;
	readOnly?: boolean;
	pvcName?: string;
	secretProviderClass?: string;
	csiDriver?: string;
};
type InlineFileFormItem = {
	path?: string;
	content?: string;
};

type FormValues = {
	label: string;
	command?: string[];
	source?: string;
	args: string[];
	env?: EnvFormItem[];
	cpu: string;
	memory: string;
	disk: string;
	gpu: string;
	computeTier: string;
	computeProfile: ComputeProfileId;
	tolerations?: TolerationFormItem[];
	volumeMounts?: VolumeMountFormItem[];
	inlineFiles?: InlineFileFormItem[];
};

const rowGridStyle = {
	display: "grid",
	gridTemplateColumns: "repeat(auto-fit, minmax(132px, 1fr)) 32px",
	gap: 8,
	alignItems: "start",
} as const;

const iconButtonStyle = { width: 32, minWidth: 32, paddingInline: 0 } as const;

function normalizeArgs(args: Argument[] | undefined): string[] {
	if (!args || args.length === 0) return [];
	return args
		.map((item) => item.value ?? item.name)
		.filter((value): value is string => Boolean(value));
}

function envToPairs(items: Argument[] | undefined): EnvFormItem[] {
	if (!items || items.length === 0) return [];
	return items.map((item) => ({
		name: item.name || "",
		value: item.value || "",
	}));
}

function formPairsToEnv(items: EnvFormItem[]): Argument[] {
	if (!items || items.length === 0) return [];
	return items
		.filter((item) => item?.name?.trim())
		.map((item) => ({
			name: item.name?.trim() || "",
			value: item.value || "",
		}));
}

function tolerationsToForm(
	items: Toleration[] | undefined,
): TolerationFormItem[] {
	if (!items || items.length === 0) return [];
	return items.map((item) => ({
		key: item.key || "",
		operator: item.operator || "",
		value: item.value || "",
		effect: item.effect || "",
		tolerationSeconds:
			item.tolerationSeconds !== undefined
				? String(item.tolerationSeconds)
				: "",
	}));
}

function formToTolerations(
	items: TolerationFormItem[] | undefined,
): Toleration[] {
	if (!items || items.length === 0) return [];
	return items
		.map((item) => {
			const key = item.key?.trim() || "";
			const operator = item.operator?.trim() || "";
			const value = item.value?.trim() || "";
			const effect = item.effect?.trim() || "";
			const rawSeconds = item.tolerationSeconds?.trim() || "";
			if (!key && !operator && !value && !effect && !rawSeconds) return null;
			const parsedSeconds = rawSeconds !== "" ? Number(rawSeconds) : undefined;
			return {
				...(key ? { key } : {}),
				...(operator ? { operator } : {}),
				...(value ? { value } : {}),
				...(effect ? { effect } : {}),
				...(parsedSeconds !== undefined && Number.isFinite(parsedSeconds)
					? { tolerationSeconds: parsedSeconds }
					: {}),
			};
		})
		.filter((item): item is Toleration => Boolean(item));
}

function volumeMountsToForm(
	items: VolumeMount[] | undefined,
): VolumeMountFormItem[] {
	if (!items || items.length === 0) return [];
	return items.map((item) => ({
		type:
			item.type ||
			(item.secretProviderClass || item.csiDriver
				? "csi"
				: item.pvcName
					? "pvc"
					: "emptyDir"),
		name: item.name || "",
		mountPath: item.mountPath || "",
		subPath: item.subPath || "",
		readOnly: item.readOnly === true,
		pvcName: item.pvcName || "",
		secretProviderClass: item.secretProviderClass || "",
		csiDriver: item.csiDriver || "",
	}));
}

function formToVolumeMounts(
	items: VolumeMountFormItem[] | undefined,
): VolumeMount[] {
	if (!items || items.length === 0) return [];
	return items.flatMap((item) => {
		const name = item.name?.trim() || "";
		const mountPath = item.mountPath?.trim() || "";
		const pvcName = item.pvcName?.trim() || "";
		const secretProviderClass = item.secretProviderClass?.trim() || "";
		const csiDriver = item.csiDriver?.trim() || "";
		if (!name && !mountPath && !pvcName && !secretProviderClass) return [];
		const type =
			item.type ||
			(secretProviderClass || csiDriver ? "csi" : pvcName ? "pvc" : "emptyDir");
		const mount: VolumeMount = {
			type,
			name,
			mountPath,
			...(item.subPath?.trim() ? { subPath: item.subPath.trim() } : {}),
			...(item.readOnly ? { readOnly: true } : {}),
			...(type === "pvc" && pvcName ? { pvcName } : {}),
			...(type === "emptyDir" ? { emptyDir: true } : {}),
			...(type === "csi" && secretProviderClass ? { secretProviderClass } : {}),
			...(type === "csi" && csiDriver ? { csiDriver } : {}),
		};
		return [mount];
	});
}

function inlineFilesToForm(
	items: InlineFile[] | undefined,
): InlineFileFormItem[] {
	if (!items || items.length === 0) return [];
	return items.map((item) => ({
		path: item.path || "",
		content: item.content || "",
	}));
}

function formToInlineFiles(
	items: InlineFileFormItem[] | undefined,
): InlineFile[] {
	if (!items || items.length === 0) return [];
	return items.flatMap((item) => {
		const filePath = item.path?.trim() || "";
		const content = item.content || "";
		if (!filePath && !content) return [];
		return [{ path: filePath, content }];
	});
}

function resolveComputeProfileValues(
	values: Pick<FormValues, "cpu" | "memory" | "disk" | "gpu" | "computeTier">,
): ComputeProfileId {
	return inferComputeProfile({
		cpu: values.cpu,
		memory: values.memory,
		disk: values.disk,
		gpu: values.gpu,
		computeTier: values.computeTier,
	});
}

function withInferredProfile(values: Partial<FormValues>): Partial<FormValues> {
	const profile = resolveComputeProfileValues({
		cpu: values.cpu || "",
		memory: values.memory || "",
		disk: values.disk || "",
		gpu: values.gpu || "",
		computeTier: values.computeTier || "",
	});
	return {
		...values,
		computeProfile: profile,
	};
}

function defaultConfigToFormValues(
	defaultConfig?: NodeDefaultConfig,
): Partial<FormValues> {
	if (!defaultConfig) return {};
	return withInferredProfile({
		command: defaultConfig.command || [],
		source: defaultConfig.source || "",
		args: defaultConfig.args?.map((item) => item.value || item.name) || [],
		env: envToPairs(defaultConfig.env),
		cpu: defaultConfig.cpu || "",
		memory: defaultConfig.memory || "",
		disk: defaultConfig.disk || "",
		gpu: defaultConfig.gpu || "",
		computeTier: defaultConfig.computeTier || "",
		tolerations: tolerationsToForm(defaultConfig.tolerations),
		volumeMounts: volumeMountsToForm(defaultConfig.volumeMounts),
		inlineFiles: inlineFilesToForm(defaultConfig.inlineFiles),
	});
}

export function NodeConfigPanel({
	open,
	node,
	onCancel,
	onSave,
}: NodeConfigPanelProps) {
	const [form] = Form.useForm<FormValues>();
	const defaultConfigValues = defaultConfigToFormValues(
		node.data.defaultConfig,
	);
	const hasDefaultConfig = Boolean(node.data.defaultConfig);

	const componentType = String(node.data.type || "").toLowerCase();
	const isScriptType = componentType === "script";
	const watchedResourceProfile = Form.useWatch("computeProfile", form);
	const watchedCpu = Form.useWatch("cpu", form);
	const watchedMemory = Form.useWatch("memory", form);
	const watchedDisk = Form.useWatch("disk", form);
	const watchedGpu = Form.useWatch("gpu", form);
	const watchedComputeTier = Form.useWatch("computeTier", form);
	const currentResourceValues = {
		cpu: (watchedCpu as string) || "",
		memory: (watchedMemory as string) || "",
		disk: (watchedDisk as string) || "",
		gpu: (watchedGpu as string) || "",
		computeTier: (watchedComputeTier as string) || "",
	};
	const activeResourceProfile = (watchedResourceProfile ||
		resolveComputeProfileValues(currentResourceValues)) as ComputeProfileId;
	const activeResourceProfileDefinition = getComputeProfileById(
		activeResourceProfile,
	);
	const resourceSummary = buildResourceSummaryFromValues(currentResourceValues);
	const showAdvancedResourceFields = activeResourceProfile === "custom";

	const applyProfileToForm = (profileId: ComputeProfileId) => {
		if (profileId === "custom") {
			form.setFieldValue("computeProfile", "custom");
			return;
		}
		const profileValues = buildResourceValues(profileId);
		form.setFieldsValue({
			...profileValues,
			computeProfile: profileId,
		});
	};

	useEffect(() => {
		if (!open) return;
		form.setFieldsValue(
			withInferredProfile({
				label: node.data.label || "",
				source: node.data.source || "",
				command: node.data.command || [],
				args: normalizeArgs(node.data.args),
				env: envToPairs(node.data.env),
				cpu: node.data.cpu || "",
				memory: node.data.memory || "",
				disk: node.data.disk || "",
				gpu: node.data.gpu || "",
				computeTier: node.data.computeTier || "",
				tolerations: tolerationsToForm(node.data.tolerations),
				volumeMounts: volumeMountsToForm(node.data.volumeMounts),
				inlineFiles: inlineFilesToForm(node.data.inlineFiles),
			}),
		);
	}, [form, node.data, open]);

	const restoreComponentDefaults = () => {
		if (!hasDefaultConfig) return;
		const nextValues = {
			...withInferredProfile(defaultConfigValues as Partial<FormValues>),
			label: node.data.label || "",
		};
		form.setFieldsValue(nextValues);
		for (const [name, value] of Object.entries(nextValues)) {
			form.setFieldValue(name as keyof FormValues, value);
		}
	};

	const handleSubmit = async () => {
		const values = await form.validateFields();
		const selectedProfile =
			values.computeProfile === "custom"
				? "custom"
				: resolveComputeProfileValues({
						cpu: values.cpu || "",
						memory: values.memory || "",
						disk: values.disk || "",
						gpu: values.gpu || "",
						computeTier: values.computeTier || "",
					});
		const resolvedProfileValues =
			selectedProfile === "custom"
				? {
						cpu: values.cpu || "",
						memory: values.memory || "",
						disk: values.disk || "",
						gpu: values.gpu || "",
						computeTier: values.computeTier || "",
					}
				: buildResourceValues(selectedProfile);
		const nextData: Partial<PipelineNodeData> = {
			label: values.label,
			source: isScriptType ? values.source : node.data.source || "",
			command: values.command || [],
			args: (values.args || []).map((value) => ({
				name: value,
				value,
			})),
			env: formPairsToEnv(values.env || []),
			cpu: resolvedProfileValues.cpu || "",
			memory: resolvedProfileValues.memory || "",
			disk: resolvedProfileValues.disk || "",
			gpu: resolvedProfileValues.gpu || "",
			computeTier: resolvedProfileValues.computeTier || "",
			tolerations: formToTolerations(values.tolerations),
			volumeMounts: formToVolumeMounts(values.volumeMounts),
			inlineFiles: formToInlineFiles(values.inlineFiles),
		};

		onSave(node.id, nextData);
		onCancel();
	};

	const requireVolumeSource =
		(fieldName: number, sourceType: "pvc" | "csi") =>
		({ getFieldValue }: { getFieldValue: (path: unknown[]) => unknown }) => ({
			validator(_: unknown, value: string | undefined) {
				const rowType = getFieldValue(["volumeMounts", fieldName, "type"]);
				if (rowType !== sourceType || value?.trim()) {
					return Promise.resolve();
				}
				return Promise.reject(
					new Error(
						sourceType === "pvc"
							? "请输入 PVC name"
							: "请输入 SecretProviderClass",
					),
				);
			},
		});

	return (
		<Modal
			title="节点配置"
			open={open}
			onCancel={onCancel}
			width={720}
			footer={
				<div style={{ display: "flex", justifyContent: "flex-end", gap: 8 }}>
					<Button onClick={onCancel}>取消</Button>
					<Button
						onClick={restoreComponentDefaults}
						disabled={!hasDefaultConfig}
					>
						恢复组件默认
					</Button>
					<Button type="primary" onClick={() => form.submit()}>
						保存
					</Button>
				</div>
			}
		>
			<Alert
				type={hasDefaultConfig ? "info" : "warning"}
				showIcon
				style={{ marginBottom: 16 }}
				message={
					hasDefaultConfig
						? "当前节点继承了组件默认配置"
						: "当前节点没有组件默认快照"
				}
				description={
					hasDefaultConfig
						? "这里看到的值是节点级覆盖值；点击「恢复组件默认」可以回到创建时的模板值。"
						: "这个节点可能来自旧流水线或手工编辑；可直接在此处修改为节点覆盖值。"
				}
			/>
			<Form form={form} layout="vertical" onFinish={handleSubmit}>
				<Form.Item label="名称" name="label">
					<Input id="node-config-label" name="label" placeholder="节点名称" />
				</Form.Item>
				{isScriptType && (
					<Form.Item label="source" name="source">
						<Input.TextArea
							id="node-config-source"
							name="source"
							rows={3}
							placeholder="Python 脚本 source"
						/>
					</Form.Item>
				)}
				<Form.Item label="命令" name="command">
					<Select
						id="node-config-command"
						mode="tags"
						options={[]}
						placeholder="按 Enter 添加命令片段"
					/>
				</Form.Item>
				<Form.Item label="参数" name="args">
					<Select
						id="node-config-args"
						mode="tags"
						options={[]}
						placeholder="按 Enter 添加参数"
					/>
				</Form.Item>
				<div
					style={{
						fontSize: 12,
						color: "#64748b",
						marginBottom: 16,
						lineHeight: 1.5,
					}}
				>
					输出组件需写入 /tmp/outputs/output，否则 Argo 会将节点标记为失败
				</div>
				<Form.Item label="环境变量">
					<Form.List name="env">
						{(fields, { add, remove }) => (
							<div style={{ display: "grid", gap: 8 }}>
								{fields.map((field) => (
									<div key={field.key} style={rowGridStyle}>
										<Form.Item
											{...field}
											name={[field.name, "name"]}
											rules={[{ required: true, message: "请输入环境变量名" }]}
											noStyle
										>
											<Input
												id={`node-config-env-name-${field.key}`}
												name={`env-${field.key}-name`}
												placeholder="KEY"
											/>
										</Form.Item>
										<Form.Item {...field} name={[field.name, "value"]} noStyle>
											<Input
												id={`node-config-env-value-${field.key}`}
												name={`env-${field.key}-value`}
												placeholder="VALUE"
											/>
										</Form.Item>
										<Tooltip title="移除环境变量">
											<Button
												type="text"
												aria-label="移除环境变量"
												icon={<MinusCircleOutlined />}
												onClick={() => remove(field.name)}
												danger
												style={iconButtonStyle}
											/>
										</Tooltip>
									</div>
								))}
								<Button
									type="dashed"
									icon={<PlusOutlined />}
									onClick={() => add()}
								>
									新增环境变量
								</Button>
							</div>
						)}
					</Form.List>
				</Form.Item>
				<Form.Item label="容忍规则">
					<Form.List name="tolerations">
						{(fields, { add, remove }) => (
							<div style={{ display: "grid", gap: 8 }}>
								{fields.map((field) => (
									<div key={field.key} style={rowGridStyle}>
										<Form.Item {...field} name={[field.name, "key"]} noStyle>
											<Input placeholder="nvidia.com/gpu" />
										</Form.Item>
										<Form.Item
											{...field}
											name={[field.name, "operator"]}
											noStyle
										>
											<Select
												options={[
													{ label: "Equal", value: "Equal" },
													{ label: "Exists", value: "Exists" },
												]}
												placeholder="操作符"
											/>
										</Form.Item>
										<Form.Item {...field} name={[field.name, "value"]} noStyle>
											<Input placeholder="present" />
										</Form.Item>
										<Form.Item {...field} name={[field.name, "effect"]} noStyle>
											<Select
												options={[
													{ label: "NoSchedule", value: "NoSchedule" },
													{
														label: "PreferNoSchedule",
														value: "PreferNoSchedule",
													},
													{ label: "NoExecute", value: "NoExecute" },
												]}
												placeholder="Effect"
											/>
										</Form.Item>
										<Form.Item
											{...field}
											name={[field.name, "tolerationSeconds"]}
											noStyle
										>
											<Input placeholder="秒数，可选" />
										</Form.Item>
										<Tooltip title="移除容忍规则">
											<Button
												type="text"
												aria-label="移除容忍规则"
												icon={<MinusCircleOutlined />}
												onClick={() => remove(field.name)}
												danger
												style={iconButtonStyle}
											/>
										</Tooltip>
									</div>
								))}
								<Button
									type="dashed"
									icon={<PlusOutlined />}
									onClick={() => add()}
								>
									新增容忍规则
								</Button>
							</div>
						)}
					</Form.List>
				</Form.Item>
				<div style={{ marginBottom: 16 }}>
					<div style={{ marginBottom: 8 }}>
						<Typography.Text strong>Volume Mounts</Typography.Text>
						<Typography.Text
							type="secondary"
							style={{ display: "block", fontSize: 12, marginTop: 2 }}
						>
							来自组件默认配置；修改后即为当前节点覆盖值。
						</Typography.Text>
					</div>
					<Form.List name="volumeMounts">
						{(fields, { add, remove }) => (
							<div style={{ display: "grid", gap: 8 }}>
								{fields.map((field) => (
									<div key={field.key} style={rowGridStyle}>
										<Form.Item {...field} name={[field.name, "type"]} noStyle>
											<Select
												options={[
													{ label: "CSI Secret", value: "csi" },
													{ label: "PVC", value: "pvc" },
													{ label: "EmptyDir", value: "emptyDir" },
												]}
											/>
										</Form.Item>
										<Form.Item
											{...field}
											name={[field.name, "name"]}
											rules={[
												{ required: true, message: "请输入 volume 名称" },
											]}
											noStyle
										>
											<Input placeholder="secrets-vol" />
										</Form.Item>
										<Form.Item
											{...field}
											name={[field.name, "mountPath"]}
											rules={[{ required: true, message: "请输入挂载路径" }]}
											noStyle
										>
											<Input placeholder="/mnt/secrets" />
										</Form.Item>
										<Form.Item
											{...field}
											name={[field.name, "pvcName"]}
											dependencies={[["volumeMounts", field.name, "type"]]}
											rules={[requireVolumeSource(field.name, "pvc")]}
											noStyle
										>
											<Input placeholder="PVC name" />
										</Form.Item>
										<Form.Item
											{...field}
											name={[field.name, "secretProviderClass"]}
											dependencies={[["volumeMounts", field.name, "type"]]}
											rules={[requireVolumeSource(field.name, "csi")]}
											noStyle
										>
											<Input placeholder="SecretProviderClass" />
										</Form.Item>
										<Form.Item
											{...field}
											name={[field.name, "subPath"]}
											noStyle
										>
											<Input placeholder="SubPath" />
										</Form.Item>
										<Form.Item
											{...field}
											name={[field.name, "readOnly"]}
											valuePropName="checked"
											noStyle
										>
											<Checkbox>只读</Checkbox>
										</Form.Item>
										<Tooltip title="移除 Volume Mount">
											<Button
												type="text"
												aria-label="移除 Volume Mount"
												icon={<MinusCircleOutlined />}
												onClick={() => remove(field.name)}
												danger
												style={iconButtonStyle}
											/>
										</Tooltip>
									</div>
								))}
								<Button
									type="dashed"
									icon={<PlusOutlined />}
									onClick={() =>
										add({
											type: "csi",
											name: "secrets-vol",
											mountPath: "/mnt/secrets",
											readOnly: true,
										})
									}
								>
									新增 Volume Mount
								</Button>
							</div>
						)}
					</Form.List>
				</div>
				<div style={{ marginBottom: 16 }}>
					<div style={{ marginBottom: 8 }}>
						<Typography.Text strong>Inline Files</Typography.Text>
						<Typography.Text
							type="secondary"
							style={{ display: "block", fontSize: 12, marginTop: 2 }}
						>
							来自组件默认配置；修改后即为当前节点覆盖值。
						</Typography.Text>
					</div>
					<Form.List name="inlineFiles">
						{(fields, { add, remove }) => (
							<div style={{ display: "grid", gap: 12 }}>
								{fields.map((field) => {
									const { key, ...restField } = field;
									return (
										<div
											key={key}
											style={{
												display: "grid",
												gridTemplateColumns: "1fr 32px",
												gap: 8,
												alignItems: "start",
											}}
										>
											<div style={{ display: "grid", gap: 8 }}>
												<Form.Item
													{...restField}
													name={[field.name, "path"]}
													rules={[
														{
															required: true,
															message: "请输入文件路径",
														},
														{
															validator: (_, value: string | undefined) => {
																if (!value || value.trim().startsWith("/")) {
																	return Promise.resolve();
																}
																return Promise.reject(
																	new Error("文件路径必须是容器内绝对路径"),
																);
															},
														},
													]}
													noStyle
												>
													<Input
														id={`node-config-inline-file-path-${key}`}
														name={`inline-file-${key}-path`}
														placeholder="/mnt/parameters/head-track-stereo.latest.yaml"
													/>
												</Form.Item>
												<Form.Item
													{...restField}
													name={[field.name, "content"]}
													noStyle
												>
													<Input.TextArea
														id={`node-config-inline-file-content-${key}`}
														name={`inline-file-${key}-content`}
														rows={5}
														placeholder={
															"pipeline_config:\n  concat_video_specs: []"
														}
													/>
												</Form.Item>
											</div>
											<Tooltip title="移除 Inline File">
												<Button
													type="text"
													aria-label="移除 Inline File"
													icon={<MinusCircleOutlined />}
													onClick={() => remove(field.name)}
													danger
													style={iconButtonStyle}
												/>
											</Tooltip>
										</div>
									);
								})}
								<Button
									type="dashed"
									icon={<PlusOutlined />}
									onClick={() =>
										add({
											path: "/mnt/parameters/head-track-stereo.latest.yaml",
											content: "pipeline_config:\n  concat_video_specs: []",
										})
									}
								>
									新增 Inline File
								</Button>
							</div>
						)}
					</Form.List>
				</div>
				<Form.Item label="计算档位" name="computeProfile">
					<Select
						id="node-config-compute-profile"
						options={computeProfileOptions}
						onChange={applyProfileToForm}
					/>
				</Form.Item>
				{!showAdvancedResourceFields ? (
					<Alert
						type="info"
						showIcon
						style={{ marginBottom: 16 }}
						message={`已应用计算档位：${
							activeResourceProfileDefinition?.label || "手动配置（高级）"
						}`}
						description={
							<Space direction="vertical" size={4}>
								<Space size={4} wrap>
									<Tag>CPU {activeResourceProfileDefinition?.cpu || "-"}</Tag>
									<Tag>
										内存 {activeResourceProfileDefinition?.memory || "-"}
									</Tag>
									<Tag>磁盘 {activeResourceProfileDefinition?.disk || "-"}</Tag>
									<Tag>GPU {activeResourceProfileDefinition?.gpu || "0"}</Tag>
								</Space>
								<Button
									size="small"
									type="link"
									onClick={() => applyProfileToForm("custom")}
								>
									切换到「手动配置（高级）」
								</Button>
							</Space>
						}
					/>
				) : (
					<div
						style={{
							display: "grid",
							gridTemplateColumns: "1fr 1fr",
							gap: 12,
						}}
					>
						<Form.Item
							label="CPU"
							name="cpu"
							extra="例如 500m、1"
							rules={[resourceQuantityRule("cpu")]}
						>
							<Input
								id="node-config-cpu"
								name="cpu"
								data-testid="node-config-resource-cpu"
								placeholder="500m"
							/>
						</Form.Item>
						<Form.Item
							label="内存"
							name="memory"
							extra="必须带单位，例如 512Mi、1Gi"
							rules={[resourceQuantityRule("memory")]}
						>
							<Input
								id="node-config-memory"
								name="memory"
								data-testid="node-config-resource-memory"
								placeholder="256Mi"
							/>
						</Form.Item>
						<Form.Item
							label="磁盘"
							name="disk"
							extra="必须带单位，例如 1Gi、20Gi"
							rules={[resourceQuantityRule("disk")]}
						>
							<Input
								id="node-config-disk"
								name="disk"
								data-testid="node-config-resource-disk"
								placeholder="1Gi"
							/>
						</Form.Item>
						<Form.Item
							label="GPU"
							name="gpu"
							extra="非负整数，例如 0、1、2"
							rules={[resourceQuantityRule("gpu")]}
						>
							<Input
								id="node-config-gpu"
								name="gpu"
								data-testid="node-config-resource-gpu"
								placeholder="1"
							/>
						</Form.Item>
						<Form.Item
							label="档位标识"
							name="computeTier"
							extra="例如 gpu-l4、cpu-low"
						>
							<Input
								id="node-config-compute-tier"
								name="computeTier"
								data-testid="node-config-resource-compute-tier"
								placeholder="gpu-l4"
							/>
						</Form.Item>
					</div>
				)}
				{showAdvancedResourceFields ? (
					<Alert
						type="info"
						showIcon
						style={{ marginBottom: 16 }}
						message="当前为手动配置（高级）"
						description={
							<Space size={4} direction="vertical">
								<Typography.Text type="secondary">
									资源会直接用于节点运行时。可在下方字段中按需调整。
								</Typography.Text>
								<Typography.Text type="secondary">
									{resourceSummary}
								</Typography.Text>
							</Space>
						}
					/>
				) : null}
			</Form>
		</Modal>
	);
}
