export function DeployPanel({
	onEditTemplate,
	_refreshKey,
	compact,
	variant,
	onViewAll,
}: {
	onEditTemplate?: (pipeline: Pipeline) => void;
	_refreshKey?: number;
	compact?: boolean;
	variant?: DeployPanelVariant;
	onViewAll?: () => void;
}) {
	void _refreshKey;
	const resolvedVariant: DeployPanelVariant =
		variant ?? (compact ? "compact" : "full");
	const navigate = useNavigate();
	const [searchParams] = useSearchParams();
	const assetIdsFromUrl = useMemo(
		() => parseRunInputIds(searchParams.get("asset_ids")),
		[searchParams],
	);
	const videoIdsFromUrl = useMemo(
		() => parseRunInputIds(searchParams.get("video_ids")),
		[searchParams],
	);
	const [templates, setTemplates] = useState<PipelineTemplate[]>([]);
	const [deployments, setDeployments] = useState<Deployment[]>([]);
	const [targets, setTargets] = useState<ExecutionTarget[]>([]);
	const [loading, setLoading] = useState(true);
	const [error, setError] = useState<string | null>(null);
	const [templateVisibleCount, setTemplateVisibleCount] =
		useState(TEMPLATE_PAGE_SIZE);
	const [selectedTemplateIds, setSelectedTemplateIds] = useState<string[]>([]);
	const [bulkDeletingTemplates, setBulkDeletingTemplates] = useState(false);
	const [deletingTemplateIds, setDeletingTemplateIds] = useState<string[]>([]);

	const [assetModalOpen, setAssetModalOpen] = useState(false);
	const [deployTargetId, setDeployTargetId] = useState<string | null>(null);
	const [selectedAssetIds, setSelectedAssetIds] = useState<string[]>([]);
	const [selectedVideoIdsText, setSelectedVideoIdsText] = useState("");
	const [selectedInputMode, setSelectedInputMode] =
		useState<RunInputMode>("asset");
	const [selectedTargetId, setSelectedTargetId] = useState<string>("default");
	const [deploying, setDeploying] = useState(false);
	const [deployError, setDeployError] = useState<string | null>(null);
	const [assetPickerResetKey, setAssetPickerResetKey] = useState(0);
	const [deployVersions, setDeployVersions] = useState<PipelineTemplate[]>([]);
	const [selectedDeployVersion, setSelectedDeployVersion] = useState<
		number | undefined
	>();
	const [parameterValues, setParameterValues] = useState<
		Record<string, unknown>
	>({});
	const [parameterErrors, setParameterErrors] = useState<
		Record<string, string>
	>({});
	const [versionDrawerOpen, setVersionDrawerOpen] = useState(false);
	const [versionDrawerTemplate, setVersionDrawerTemplate] =
		useState<PipelineTemplate | null>(null);
	const [activeVersionByTemplate, setActiveVersionByTemplate] = useState<
		Record<string, number>
	>({});

	const displayTemplates = useMemo(
		() => dedupeTemplatesByName(templates),
		[templates],
	);
	const displayDeployments = useMemo(
		() => prepareDeployments(deployments),
		[deployments],
	);
	const selectedDeployTemplate = useMemo(() => {
		if (!selectedDeployVersion) {
			return deployVersions[0];
		}
		return (
			deployVersions.find(
				(template) => template.version === selectedDeployVersion,
			) ?? deployVersions[0]
		);
	}, [deployVersions, selectedDeployVersion]);
	const selectedParameters = useMemo(
		() =>
			selectedDeployTemplate?.parameters ??
			selectedDeployTemplate?.pipeline?.parameters ??
			[],
		[selectedDeployTemplate],
	);
	const selectedVideoIds = useMemo(
		() => parseRunInputIds(selectedVideoIdsText),
		[selectedVideoIdsText],
	);
	const selectedDeployValidation = useMemo(() => {
		if (!selectedDeployTemplate?.pipeline) return null;
		return validatePipelineForRun(selectedDeployTemplate.pipeline);
	}, [selectedDeployTemplate]);
	const selectedDeployErrors = selectedDeployValidation?.errors ?? [];

	const refresh = useCallback(async () => {
		setLoading(true);
		setError(null);
		try {
			const shouldLoadDeployments = resolvedVariant === "compact";
			const [d, t, executionTargets] = await Promise.all([
				shouldLoadDeployments ? listDeployments() : Promise.resolve([]),
				listPipelines(),
				listExecutionTargets(),
			]);
			setDeployments(d);
			setTemplates(t);
			const activeMap: Record<string, number> = {};
			for (const template of t) {
				if (
					template.activeVersion != null &&
					template.activeVersion > 0 &&
					template.activeVersion < template.version
				) {
					activeMap[template.name] = template.activeVersion;
				}
			}
			setActiveVersionByTemplate(activeMap);
			setSelectedTemplateIds((prev) =>
				prev.filter((id) => t.some((template) => template.id === id)),
			);
			setTargets(executionTargets);
			const defaultTarget =
				executionTargets.find((target) => target.isDefault) ??
				executionTargets[0];
			if (defaultTarget) setSelectedTargetId(defaultTarget.id);
		} catch (err) {
			const detail = err instanceof Error ? err.message : String(err);
			setError(detail);
			setDeployments([]);
			setTemplates([]);
			setTargets([]);
		} finally {
			setLoading(false);
		}
	}, [resolvedVariant]);

	useEffect(() => {
		refresh();
	}, [refresh]);

	useEffect(() => {
		setTemplateVisibleCount(TEMPLATE_PAGE_SIZE);
	}, []);

	useEffect(() => {
		if (!assetModalOpen) return;
		setParameterValues(defaultParameterValues(selectedParameters));
		setParameterErrors({});
	}, [assetModalOpen, selectedParameters]);

	const handleDeployClick = (templateId: string) => {
		const currentTemplate = templates.find(
			(template) => template.id === templateId,
		);
		const hasVideoIds = videoIdsFromUrl.length > 0;
		setDeployTargetId(templateId);
		setDeployVersions(currentTemplate ? [currentTemplate] : []);
		const activeVersion = activeVersionByTemplate[currentTemplate?.name ?? ""];
		setSelectedDeployVersion(activeVersion ?? currentTemplate?.version);
		setSelectedAssetIds(assetIdsFromUrl);
		setSelectedVideoIdsText(videoIdsFromUrl.join("\n"));
		setSelectedInputMode(
			!hasVideoIds || assetIdsFromUrl.length > 0 ? "asset" : "video",
		);
		setDeployError(null);
		setAssetPickerResetKey((key) => key + 1);
		const defaultTarget =
			targets.find((target) => target.isDefault) ?? targets[0];
		setSelectedTargetId(defaultTarget?.id ?? "default");
		setAssetModalOpen(true);
		listPipelineVersions(templateId)
			.then((versions) => {
				const nextVersions =
					versions.length > 0
						? versions
						: currentTemplate
							? [currentTemplate]
							: [];
				setDeployVersions(nextVersions);
				if (nextVersions.length > 0) {
					setSelectedDeployVersion(
						activeVersion ??
							currentTemplate?.version ??
							nextVersions[0]?.version,
					);
				}
			})
			.catch((err) => {
				message.warning(`版本列表加载失败，将运行当前版本: ${String(err)}`);
			});
	};

	const closeAssetModal = () => {
		setAssetModalOpen(false);
		setSelectedAssetIds([]);
		setSelectedVideoIdsText("");
		setSelectedInputMode("asset");
		setDeployVersions([]);
		setSelectedDeployVersion(undefined);
		setParameterValues({});
		setParameterErrors({});
		setDeployError(null);
		setAssetPickerResetKey((key) => key + 1);
	};

	const handleDeployConfirm = async () => {
		if (deploying) return;
		if (!deployTargetId) return;
		if (selectedDeployErrors.length > 0) return;
		const errors = validateParameterValues(selectedParameters, parameterValues);
		setParameterErrors(errors);
		if (Object.keys(errors).length > 0) return;
		const resolvedParameterValues = Object.fromEntries(
			(selectedParameters ?? [])
				.map((parameter) => [
					parameter.name,
					coerceParameterInput(parameter, parameterValues[parameter.name]),
				])
				.filter(([, value]) => value !== undefined),
		);
		const assetIds = selectedInputMode === "asset" ? selectedAssetIds : [];
		const videoIds =
			selectedInputMode === "video" ? selectedVideoIds : undefined;
		setDeploying(true);
		setDeployError(null);
		try {
			const shouldBatchDeploy =
				(selectedInputMode === "asset" && assetIds.length > 1) ||
				(selectedInputMode === "video" && (videoIds?.length ?? 0) > 1);
			if (selectedInputMode === "video") {
				if (shouldBatchDeploy) {
					const result = await batchDeployTemplate(
						deployTargetId,
						[],
						selectedTargetId,
						selectedDeployVersion,
						resolvedParameterValues,
						videoIds,
					);
					message.success(
						result.accepted
							? `批量任务已提交，后台继续规划 ${result.pendingCount ?? 0} 个批次`
							: "批量任务已提交",
					);
				} else {
					await deployTemplate(
						deployTargetId,
						assetIds,
						selectedTargetId,
						selectedDeployVersion,
						resolvedParameterValues,
						videoIds,
					);
					message.success("部署成功");
				}
			} else if (shouldBatchDeploy) {
				const result = await batchDeployTemplate(
					deployTargetId,
					assetIds,
					selectedTargetId,
					selectedDeployVersion,
					resolvedParameterValues,
				);
				message.success(
					result.accepted
						? `批量任务已提交，后台继续规划 ${result.pendingCount ?? 0} 个批次`
						: "批量任务已提交",
				);
			} else {
				await deployTemplate(
					deployTargetId,
					assetIds,
					selectedTargetId,
					selectedDeployVersion,
					resolvedParameterValues,
				);
				message.success("部署成功");
			}
			closeAssetModal();
			setDeploying(false);
			void refresh();
		} catch (err) {
			const errorMessage = formatDeployError(err);
			setDeployError(errorMessage);
			setDeploying(false);
		}
	};

	const handleDeleteTemplate = async (id: string) => {
		setDeletingTemplateIds((prev) => Array.from(new Set([...prev, id])));
		try {
			await deletePipeline(id);
			message.success("已删除流水线模板");
			await refresh();
		} catch (err) {
			message.error(`删除失败: ${String(err)}`);
		} finally {
			setDeletingTemplateIds((prev) => prev.filter((item) => item !== id));
		}
	};

	const handleBulkDeleteTemplates = async () => {
		if (selectedTemplateIds.length === 0) return;
		setBulkDeletingTemplates(true);
		try {
			const results = await Promise.allSettled(
				selectedTemplateIds.map((id) => deletePipeline(id)),
			);
			const failedCount = results.filter(
				(result) => result.status === "rejected",
			).length;
			const deletedCount = results.length - failedCount;
			if (deletedCount > 0) {
				message.success(`已删除 ${deletedCount} 条流水线`);
			}
			if (failedCount > 0) {
				message.error(`${failedCount} 条流水线删除失败`);
			}
			setSelectedTemplateIds([]);
			await refresh();
		} finally {
			setBulkDeletingTemplates(false);
		}
	};

	const handleEditTemplate = async (id: string) => {
		try {
			const t = await getPipeline(id);
			if (onEditTemplate) {
				onEditTemplate(t.pipeline);
			} else {
				navigate(`/pipeline?templateId=${encodeURIComponent(id)}`);
			}
		} catch (err) {
			message.error(`加载模板失败: ${String(err)}`);
		}
	};

	const handleVersionHistory = (template: PipelineTemplate) => {
		setVersionDrawerTemplate(template);
		setVersionDrawerOpen(true);
	};

	const handleSetActiveVersion = async (
		template: PipelineTemplate,
		version: number,
	) => {
		try {
			await setPipelineActiveVersion(template.id, version);
			setActiveVersionByTemplate((prev) => ({
				...prev,
				[template.name]: version,
			}));
			message.success(
				`已将 ${template.name} 的活跃版本设为 v${version}，下次运行将默认使用此版本`,
			);
			await refresh();
		} catch (err) {
			message.error(`设置活跃版本失败: ${String(err)}`);
		}
	};

	const renderTemplateSection = (
		items: PipelineTemplate[],
		options?: { compactActions?: boolean; emptyLabel?: string },
	) => {
		if (loading) {
			return <PanelSkeleton rows={resolvedVariant === "sidebar" ? 2 : 3} />;
		}
		if (items.length === 0) {
			return (
				<PipelineEmptyState
					variant="deploy"
					title={options?.emptyLabel ?? "暂无已保存的流水线模板"}
				/>
			);
		}
		return items.map((t) => (
			<TemplateCard
				key={t.id}
				template={t}
				onRun={handleDeployClick}
				onEdit={handleEditTemplate}
				onDelete={handleDeleteTemplate}
				onVersionHistory={handleVersionHistory}
				activeVersion={activeVersionByTemplate[t.name]}
				compactActions={options?.compactActions}
				selectable={resolvedVariant === "full"}
				selected={selectedTemplateIds.includes(t.id)}
				deleting={deletingTemplateIds.includes(t.id)}
				onSelect={(id, checked) =>
					setSelectedTemplateIds((prev) =>
						checked
							? Array.from(new Set([...prev, id]))
							: prev.filter((item) => item !== id),
					)
				}
			/>
		));
	};

	if (resolvedVariant === "sidebar") {
		const sidebarTemplates = displayTemplates.slice(0, SIDEBAR_TEMPLATE_LIMIT);
		const hiddenCount = Math.max(
			displayTemplates.length - sidebarTemplates.length,
			0,
		);

		return (
			<div className="deploy-panel deploy-panel--sidebar">
				<div className="deploy-panel-sidebar__header">
					<div className="deploy-panel-sidebar__title">已保存</div>
					{!loading ? (
						<span className="count">{displayTemplates.length}</span>
					) : null}
				</div>
				{error ? (
					<Alert
						type="error"
						showIcon
						message="加载失败"
						description={error}
						action={
							<Button size="small" onClick={refresh} loading={loading}>
								重试
							</Button>
						}
						style={{ marginBottom: 12, fontSize: 12 }}
					/>
				) : null}
				<div className="deploy-section deploy-section--sidebar">
					{renderTemplateSection(sidebarTemplates, {
						compactActions: true,
					})}
				</div>
				{hiddenCount > 0 || onViewAll ? (
					<div className="deploy-panel-sidebar__footer">
						{hiddenCount > 0 ? (
							<span className="deploy-panel-sidebar__hint">
								还有 {hiddenCount} 个模板未显示
							</span>
						) : null}
						{onViewAll ? (
							<Button type="link" size="small" onClick={onViewAll}>
								查看全部
							</Button>
						) : null}
					</div>
				) : null}
			</div>
		);
	}

	if (resolvedVariant === "compact") {
		const recentDeployments = displayDeployments.slice(0, 3);
		const compactTemplates = displayTemplates.slice(0, COMPACT_TEMPLATE_LIMIT);
		const hiddenTemplates = Math.max(
			displayTemplates.length - compactTemplates.length,
			0,
		);

		return (
			<div className="deploy-panel deploy-panel--compact">
				{error ? (
					<Alert
						type="error"
						showIcon
						message="加载失败"
						description={error}
						action={
							<Button size="small" onClick={refresh} loading={loading}>
								重试
							</Button>
						}
						style={{ marginBottom: 12, fontSize: 12 }}
					/>
				) : null}
				<div className="deploy-panel-compact__section-header">
					<div className="deploy-section-title">最近执行</div>
					<Link
						to="/pipeline?tab=executions"
						className="deploy-panel-compact__link"
					>
						查看全部
					</Link>
				</div>

				<div className="deploy-section">
					{loading ? (
						<PanelSkeleton rows={2} />
					) : recentDeployments.length === 0 ? (
						<PipelineEmptyState variant="deploy" title="暂无执行记录" />
					) : (
						recentDeployments.map((d) => (
							<div key={d.id} className="dep-card">
								<div className="dep-card-info">
									<div className="dep-card-name">{d.pipelineName}</div>
									<div className="dep-card-meta">
										<Tag color={STATUS_COLORS[d.status] || "default"}>
											{d.status}
										</Tag>
									</div>
								</div>
								<Button
									size="small"
									icon={<LinkOutlined />}
									onClick={() =>
										navigate(
											`/pipeline/executions/${d.workflowName}${d.id ? `?runId=${encodeURIComponent(d.id)}` : ""}`,
										)
									}
								>
									查看
								</Button>
							</div>
						))
					)}
				</div>

				<div className="deploy-section-title deploy-panel-compact__templates-title">
					模板
					{!loading ? (
						<span className="count">{displayTemplates.length}</span>
					) : null}
				</div>
				<div className="deploy-section">
					{renderTemplateSection(compactTemplates, {
						compactActions: true,
						emptyLabel: "暂无已保存的流水线模板",
					})}
				</div>
				{hiddenTemplates > 0 ? (
					<div className="deploy-panel-compact__hint">
						还有 {hiddenTemplates} 个同名模板已折叠
					</div>
				) : null}
			</div>
		);
	}

	const visibleTemplates = displayTemplates.slice(0, templateVisibleCount);
	const selectableTemplateIds = displayTemplates.map((template) => template.id);
	const selectedTemplateIdSet = new Set(selectedTemplateIds);
	const allTemplatesSelected =
		selectableTemplateIds.length > 0 &&
		selectableTemplateIds.every((id) => selectedTemplateIdSet.has(id));
	const someTemplatesSelected =
		selectedTemplateIds.length > 0 && !allTemplatesSelected;
	const selectedInputIds =
		selectedInputMode === "video" ? selectedVideoIds : selectedAssetIds;
	const selectionSnapshotPreview = getSelectionSnapshotPreview(
		selectedInputMode,
		selectedInputIds.length,
		selectedDeployTemplate?.nodeCount,
	);
	const runActionLabel = getRunActionLabel(
		selectedInputMode,
		selectedInputIds.length,
	);
	const runInputSummary = getRunInputSummary(
		selectedInputMode,
		selectedInputIds.length,
	);
	const urlInputSummary =
		assetIdsFromUrl.length > 0
			? { mode: "asset" as const, count: assetIdsFromUrl.length }
			: videoIdsFromUrl.length > 0
				? { mode: "video" as const, count: videoIdsFromUrl.length }
				: null;

	return (
		<div className="deploy-panel">
			<div className="deploy-panel__toolbar">
				<h3>流水线管理</h3>
				<Space>
					<Button
						size="small"
						icon={<LinkOutlined />}
						onClick={() => navigate("/pipeline?tab=executions")}
					>
						执行记录
					</Button>
					<Button
						size="small"
						icon={<ReloadOutlined />}
						onClick={refresh}
						loading={loading}
					>
						刷新
					</Button>
				</Space>
			</div>

			{urlInputSummary ? (
				<Alert
					type="info"
					showIcon
					message={`已选择 ${urlInputSummary.count} 个${urlInputSummary.mode === "video" ? "视频" : "资产"}`}
					description="请选择要运行的流水线和版本，确认后即可提交运行。"
					style={{ marginBottom: 12, fontSize: 12 }}
				/>
			) : null}

			{error ? (
				<Alert
					type="error"
					showIcon
					message="加载失败"
					description={error}
					action={
						<Button size="small" onClick={refresh} loading={loading}>
							重试
						</Button>
					}
					style={{ marginBottom: 16, fontSize: 12 }}
				/>
			) : null}

			<div className="deploy-panel__section-card">
				<div className="deploy-section-title">
					<div>
						已保存的流水线
						{!loading ? (
							<span className="count">{displayTemplates.length}</span>
						) : null}
					</div>
					{!loading && displayTemplates.length > 0 ? (
						<Space>
							<Checkbox
								checked={allTemplatesSelected}
								indeterminate={someTemplatesSelected}
								onChange={(event) =>
									setSelectedTemplateIds(
										event.target.checked ? selectableTemplateIds : [],
									)
								}
							>
								全选
							</Checkbox>
							{/* #22: Ant Design Popconfirm's description text leaks into aria-describedby.
							   Known Ant Design Popover ARIA propagation issue. */}
							<Popconfirm
								title={`删除选中的 ${selectedTemplateIds.length} 条流水线？`}
								description="删除后不可恢复"
								okText="删除"
								cancelText="取消"
								disabled={selectedTemplateIds.length === 0}
								onConfirm={handleBulkDeleteTemplates}
							>
								<Button
									size="small"
									danger
									icon={<DeleteOutlined />}
									disabled={selectedTemplateIds.length === 0}
									loading={bulkDeletingTemplates}
								>
									批量删除
									{selectedTemplateIds.length > 0
										? `（${selectedTemplateIds.length}）`
										: ""}
								</Button>
							</Popconfirm>
						</Space>
					) : null}
				</div>
				<div className="deploy-section">
					{renderTemplateSection(visibleTemplates)}
				</div>
				{displayTemplates.length > visibleTemplates.length ? (
					<Button
						type="link"
						size="small"
						className="deploy-panel__load-more"
						onClick={() => {
							const remaining =
								displayTemplates.length - visibleTemplates.length;
							setTemplateVisibleCount(
								remaining <= TEMPLATE_PAGE_SIZE
									? displayTemplates.length
									: (count) => count + TEMPLATE_PAGE_SIZE,
							);
						}}
					>
						加载更多模板（还剩{" "}
						{displayTemplates.length - visibleTemplates.length} 条）
					</Button>
				) : null}
			</div>

			<Modal
				title="运行流水线"
				open={assetModalOpen}
				onCancel={closeAssetModal}
				onOk={handleDeployConfirm}
				confirmLoading={deploying}
				okText={runActionLabel}
				okButtonProps={{ disabled: selectedDeployErrors.length > 0 }}
				width={640}
			>
				<Alert
					type={selectedInputIds.length > 0 ? "success" : "warning"}
					message={runInputSummary.message}
					description={runInputSummary.description}
					showIcon
					style={{ marginBottom: 16, fontSize: 12 }}
				/>
				<Alert
					type={selectionSnapshotPreview.type}
					message={selectionSnapshotPreview.message}
					description={
						<Space direction="vertical" size={4}>
							<Typography.Text>
								{selectionSnapshotPreview.description}
							</Typography.Text>
							<Space size={[6, 6]} wrap>
								<Tag color="blue">
									{selectionSnapshotPreview.inputLabel}{" "}
									{selectedInputIds.length.toLocaleString()}
								</Tag>
								<Tag color="geekblue">
									预计批次{" "}
									{selectionSnapshotPreview.childTasks.toLocaleString()}
								</Tag>
								<Tag>Snapshot ID 提交后生成</Tag>
							</Space>
						</Space>
					}
					showIcon
					style={{ marginBottom: 16, fontSize: 12 }}
				/>
				{deployError ? (
					<Alert
						type="error"
						message="部署失败"
						description={deployError}
						action={
							<Button
								size="small"
								danger
								loading={deploying}
								onClick={handleDeployConfirm}
							>
								重试
							</Button>
						}
						showIcon
						style={{ marginBottom: 16, fontSize: 12 }}
					/>
				) : null}
				{selectedDeployErrors.length > 0 ? (
					<Alert
						type="error"
						message="当前版本不可运行"
						description={selectedDeployErrors.slice(0, 3).join("；")}
						showIcon
						style={{ marginBottom: 16, fontSize: 12 }}
					/>
				) : null}
				<div className="deploy-run-field">
					<div className="deploy-run-field__label">模板版本</div>
					<div className="deploy-run-field__hint">
						默认使用活跃版本；也可以在这里选择历史版本运行。
					</div>
					<Select
						aria-label="模板版本"
						value={selectedDeployVersion}
						onChange={(version) => {
							setSelectedDeployVersion(version);
							setDeployError(null);
						}}
						style={{ width: "100%", marginBottom: 12 }}
						options={deployVersions.map((version) => ({
							value: version.version,
							label: `版本 v${version.version} · ${version.nodeCount} 个步骤 · 保存于 ${new Date(
								version.createdAt,
							).toLocaleString()}`,
						}))}
					/>
				</div>
				{selectedParameters.length > 0 ? (
					<div className="deploy-run-field">
						<div className="deploy-run-field__label">运行参数</div>
						<Space direction="vertical" size={12} style={{ width: "100%" }}>
							{selectedParameters.map((parameter) => {
								const value = parameterValues[parameter.name];
								const error = parameterErrors[parameter.name];
								const label = (
									<Space size={6}>
										<span>{parameter.name}</span>
										{parameter.required ? <Tag color="red">必填</Tag> : null}
										{parameter.secret ? <Tag>Secret</Tag> : null}
									</Space>
								);
								return (
									<div key={parameter.name}>
										<Typography.Text strong>{label}</Typography.Text>
										{parameter.description ? (
											<div className="deploy-run-field__hint">
												{parameter.description}
											</div>
										) : null}
										{parameter.options?.length ? (
											<Select
												aria-label={parameter.name}
												value={value}
												onChange={(nextValue) => {
													setParameterValues((current) => ({
														...current,
														[parameter.name]: nextValue,
													}));
												}}
												style={{ width: "100%" }}
												options={parameter.options.map((option) => ({
													value: option,
													label: String(option),
												}))}
											/>
										) : parameter.type === "boolean" ? (
											<Checkbox
												checked={Boolean(value)}
												onChange={(event) => {
													setParameterValues((current) => ({
														...current,
														[parameter.name]: event.target.checked,
													}));
												}}
											>
												true
											</Checkbox>
										) : shouldUseParameterTextArea(parameter, value) ? (
											<Input.TextArea
												aria-label={parameter.name}
												value={typeof value === "string" ? value : ""}
												autoSize={{ minRows: 4, maxRows: 12 }}
												placeholder="支持多行 YAML / JSON / 文本"
												onChange={(event) => {
													setParameterValues((current) => ({
														...current,
														[parameter.name]: event.target.value,
													}));
												}}
												status={error ? "error" : undefined}
											/>
										) : (
											<Input
												aria-label={parameter.name}
												type={
													parameter.secret
														? "password"
														: parameter.type === "number" ||
																parameter.type === "integer"
															? "number"
															: "text"
												}
												value={value == null ? "" : String(value)}
												onChange={(event) => {
													setParameterValues((current) => ({
														...current,
														[parameter.name]: event.target.value,
													}));
												}}
											/>
										)}
										{error ? (
											<Typography.Text type="danger">{error}</Typography.Text>
										) : null}
									</div>
								);
							})}
						</Space>
					</div>
				) : null}
				<div className="deploy-run-field">
					<div className="deploy-run-field__label">执行目标</div>
					<div className="deploy-run-field__hint">
						当前版本只选择执行目标；Resource Pool / Queue
						由后端调度策略决定，独立选择器需后端返回可选资源池。
					</div>
					<Select
						value={selectedTargetId}
						onChange={setSelectedTargetId}
						style={{ width: "100%" }}
						options={(targets.length > 0
							? targets
							: [
									{
										id: "default",
										name: "Default Argo target",
										namespace: "default",
										cluster: "default",
										status: "unavailable",
										enabled: false,
										isDefault: true,
										argoServerConfigured: false,
									} satisfies ExecutionTarget,
								]
						).map((target) => ({
							value: target.id,
							label: `${target.name} · ${target.cluster}/${target.namespace}`,
							disabled: target.status !== "available" || !target.enabled,
						}))}
					/>
				</div>
				<RunInputSelector
					mode={selectedInputMode}
					onModeChange={setSelectedInputMode}
					assetIds={selectedAssetIds}
					onAssetIdsChange={setSelectedAssetIds}
					videoIdsText={selectedVideoIdsText}
					onVideoIdsTextChange={setSelectedVideoIdsText}
					maxHeight={300}
					resetKey={assetPickerResetKey}
				/>
			</Modal>
			{versionDrawerTemplate ? (
				<VersionHistoryDrawer
					open={versionDrawerOpen}
					pipelineName={versionDrawerTemplate.name}
					templateId={versionDrawerTemplate.id}
					activeVersion={activeVersionByTemplate[versionDrawerTemplate.name]}
					onClose={() => {
						setVersionDrawerOpen(false);
						setVersionDrawerTemplate(null);
					}}
					onSetActive={(version) =>
						handleSetActiveVersion(versionDrawerTemplate, version)
					}
				/>
			) : null}
		</div>
	);
}
