import { Input, Segmented, Space } from "antd";
import { useMemo } from "react";
import AssetPicker from "./AssetPicker";
import { parseRunInputIds, type RunInputMode } from "./runInputUtils";

export interface RunInputSelectorProps {
	mode: RunInputMode;
	onModeChange: (mode: RunInputMode) => void;
	assetIds: string[];
	onAssetIdsChange: (ids: string[]) => void;
	videoIdsText: string;
	onVideoIdsTextChange: (text: string) => void;
	resetKey?: string | number;
	maxHeight?: number;
}

export function RunInputSelector({
	mode,
	onModeChange,
	assetIds,
	onAssetIdsChange,
	videoIdsText,
	onVideoIdsTextChange,
	resetKey,
	maxHeight = 200,
}: RunInputSelectorProps) {
	const parsedVideoIds = useMemo(
		() => parseRunInputIds(videoIdsText),
		[videoIdsText],
	);

	return (
		<Space direction="vertical" size={12} style={{ width: "100%" }}>
			<div className="deploy-run-field">
				<div className="deploy-run-field__label">输入来源</div>
				<div className="deploy-run-field__hint">
					可在资产搜索与视频 ID
					手填之间切换；提交时会冻结当前输入为本次运行快照。
				</div>
				<Segmented
					aria-label="输入来源"
					value={mode}
					onChange={(value) => onModeChange(value as RunInputMode)}
					options={[
						{ label: "资产 IDs", value: "asset" },
						{ label: "视频 IDs", value: "video" },
					]}
				/>
			</div>

			{mode === "asset" ? (
				<AssetPicker
					selectedIds={assetIds}
					onSelectionChange={onAssetIdsChange}
					maxHeight={maxHeight}
					resetKey={resetKey}
				/>
			) : (
				<div className="deploy-run-field">
					<div className="deploy-run-field__label">视频 IDs</div>
					<div className="deploy-run-field__hint">
						每行或逗号分隔，支持 UUID 等视频标识；提交后这些 ID
						会固定到本次运行。
					</div>
					<Input.TextArea
						aria-label="视频 IDs"
						name="pipelineRunVideoIds"
						value={videoIdsText}
						onChange={(event) => onVideoIdsTextChange(event.target.value)}
						placeholder={
							"例如：\n019dabf3-5685-769f-8ec3-3992767ebe65\n019dabf3-8b65-7541-b3d8-bba201ca7781"
						}
						autoSize={{ minRows: 4, maxRows: 10 }}
					/>
					<div
						style={{
							fontSize: 12,
							color: "#64748b",
							marginTop: 6,
						}}
					>
						已识别 {parsedVideoIds.length} 个视频 ID
					</div>
				</div>
			)}
		</Space>
	);
}
