import { extractApiErrorMessage } from "./apiError";

export function formatDeployError(err: unknown) {
	const raw = extractApiErrorMessage(err, "部署失败");
	const missingCommandMatch = raw.match(
		/node "([^"]+)" container command or args is required/i,
	);
	if (missingCommandMatch) {
		return `流水线配置无效：节点「${missingCommandMatch[1]}」缺少容器命令或参数，请先编辑该节点后再运行。`;
	}
	return raw.replace(/^invalid argument:\s*/i, "");
}
