const formatDateTime = (value?: string): string =>
	value ? new Date(value).toLocaleString() : "-";

function splitImageReference(value: string): {
	repository: string;
	tag: string;
} {
	const image = (value || "").trim();
	if (!image) return { repository: "", tag: "" };
	if (image.includes("@")) return { repository: image, tag: "" };
	const lastSlashIndex = image.lastIndexOf("/");
	const lastColonIndex = image.lastIndexOf(":");
	if (lastColonIndex > lastSlashIndex && lastColonIndex < image.length - 1) {
		return {
			repository: image.slice(0, lastColonIndex),
			tag: image.slice(lastColonIndex + 1),
		};
	}
	return { repository: image, tag: "" };
}

function parseImageRepository(value: string): string {
	return splitImageReference(value).repository;
}

function parseImageTag(value: string, tag?: string): string {
	const embeddedTag = splitImageReference(value).tag;
	if (embeddedTag) return embeddedTag;
	const normalizedTag = (tag || "").trim();
	if (normalizedTag) return normalizedTag;
	return "";
}

function getImageWithTag(values: { image?: string; tag?: string }): string {
	const image = (values.image || "").trim();
	const tag = (values.tag || "").trim();
	if (!image) return "";
	const repository = parseImageRepository(image);
	const resolvedTag = parseImageTag(image, tag);
	return resolvedTag ? `${repository}:${resolvedTag}` : repository;
}

async function validateImageRepository(_: unknown, value?: string) {
	const image = (value || "").trim();
	if (!image) {
		throw new Error("请输入镜像仓库");
	}
	if (/\s/.test(image)) {
		throw new Error("镜像仓库不能包含空格");
	}
	if (!/^(?=.{1,255}$)[a-z0-9][a-z0-9._-]*(\/[a-z0-9._-]+)*$/.test(image)) {
		throw new Error(
			"镜像仓库格式不正确，例如：alpine、python、registry.example.com/team/image",
		);
	}
	if (parseImageTag(image).length > 0 && image.includes(":")) {
		throw new Error("检测到 tag，建议填入 Image Tag 字段（仓库不要带 tag）");
	}
}

function hasPathRows(
	items?: { path?: string; [key: string]: unknown }[],
): boolean {
	if (!items || items.length === 0) return false;
	return items.some((item) =>
		Object.values(item).some((value) => String(value || "").trim().length > 0),
	);
}

function hasValue(
	items?: Record<string, unknown>[] | null,
	fields: string[] = [
		"name",
		"value",
		"path",
		"mountPath",
		"csiDriver",
		"type",
	],
): boolean {
	if (!items || items.length === 0) return false;
	return items.some((item) =>
		fields.some(
			(field) =>
				String((item as Record<string, unknown>)[field] || "").trim().length >
				0,
		),
	);
}

function getPortPreviewPath(prefix: string, name: string) {
	const normalizedName = name.trim();
	return `${prefix}/${normalizedName || "-"}`;
}

function validatePortName(
	currentValue: string | undefined,
	ports: PortRow[] | undefined,
	currentIndex: number | string,
) {
	const value = (currentValue || "").trim();
	if (!value) {
		throw new Error("请输入名称");
	}
	if (!PORT_NAME_PATTERN.test(value)) {
		throw new Error(
			"名称仅支持英文字母、数字、下划线、短横线，且不能以数字开头",
		);
	}
	const lower = value.toLowerCase();
	if (RESERVED_PORT_NAMES.has(lower)) {
		throw new Error(`名称“${value}”为平台保留名，不能使用`);
	}
	const normalizedIndex = Number(currentIndex);
	const exists = (ports || []).filter((item, index) => {
		if (!Number.isNaN(normalizedIndex) && index === normalizedIndex) {
			return false;
		}
		return (item.name || "").trim().toLowerCase() === lower;
	}).length;
	if (exists > 0) {
		throw new Error("名称不能重复");
	}
}

function formatShellToken(token: string): string {
	const value = token.trim();
	if (!value) return "";
	if (/[\s"'`$]/.test(value)) return JSON.stringify(value);
	return value;
}

const splitInputItems = (value?: string): string[] =>
	(value || "")
		.split(/\s+/)
		.map((v) => v.trim())
		.filter(Boolean);

function parseCommandItems(value?: string): string[] {
	const raw = (value || "").trim();
	if (!raw) return [];
	if (raw.startsWith("[")) {
		let parsed: unknown;
		try {
			parsed = JSON.parse(raw);
		} catch {
			throw new Error("命令请用空格分隔多个启动项，例如：python /app/main.py");
		}
		if (
			!Array.isArray(parsed) ||
			!parsed.every((item) => typeof item === "string")
		) {
			throw new Error("命令 JSON 必须是字符串数组");
		}
		return parsed.map((item) => item.trim()).filter(Boolean);
	}
	return splitInputItems(raw);
}

const joinInputItems = (value?: string[]): string =>
	(value || [])
		.map((item) => item.trim())
		.filter(Boolean)
		.join(" ");

const resourceString = (
	resources: Record<string, unknown> | undefined,
	key: string,
): string => {
	const value = resources?.[key];
	return typeof value === "string" ? value : "";
};

